create table cp7_credit.source_operation_completions_v1(
 operation_id uuid primary key references cp7_credit.source_operation_materializations_v1(operation_id),
 final_native_source jsonb not null,final_profile jsonb not null,final_manifest_sha256 text not null,
 recorded_at timestamptz not null default statement_timestamp(),
 check(final_manifest_sha256~'^[0-9a-f]{64}$')
);

create function cp7_credit.part_lines(p_part uuid) returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare q cp7_credit.component_parts;c cp7_credit.recognition_components;h cp7_credit.cohorts;ar uuid;
begin
 select *into strict q from cp7_credit.component_parts where id=p_part;
 select *into strict c from cp7_credit.recognition_components where id=q.component_id;
 select h0.*into strict h from cp7_credit.cohorts h0 join cp7_credit.recognition_plans p on p.cohort_id=h0.id where p.id=c.plan_id;
 -- Actual AR account of this return journal, under mapping/account locks.
 -- The source collector must reject unexplained account changes, not invent a
-- reclassification from some unrelated account or choose a new default.
 select distinct jl.account_id into strict ar from erp.journal_lines jl
  where jl.journal_entry_id=h.source_return_journal_id
   and jl.account_id=h.ar_account_id and jl.customer_id=h.customer_id and jl.credit>0;
 if ar=h.credit_account_id then raise exception 'CP7_CREDIT_ACCOUNT_COLLISION';end if;
 return cp7_credit.native_cent_lines(jsonb_build_array(
  jsonb_build_object('account_id',ar,'customer_id',h.customer_id,
   'description','OW04 source-bound recognition',
   'debit',case when q.amount>0 then q.amount else 0 end,
   'credit',case when q.amount<0 then -q.amount else 0 end),
  jsonb_build_object('account_id',h.credit_account_id,'customer_id',h.customer_id,
   'description','OW04 source-bound recognition',
   'debit',case when q.amount<0 then -q.amount else 0 end,
   'credit',case when q.amount>0 then q.amount else 0 end)));
end $$;

create function cp7_credit.assert_bound_post(p_type text,p_source uuid,p_economic date,p_lines jsonb)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare x cp7_credit.posting_scope;c cp7_credit.recognition_components;q cp7_credit.component_parts;h cp7_credit.cohorts;
begin
 select *into strict x from cp7_credit.posting_scope where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid();
 if auth.uid()is null or auth.jwt()->>'role'is distinct from'authenticated'
  or(x.source_type,x.source_id,x.economic_date,x.lines_sha256_pg)is distinct from
   (p_type,p_source,p_economic,cp7_credit.native_lines_sha256(p_lines))then
  raise exception using errcode='42501',message='CP7_CREDIT_PAIRED_POST_SCOPE_REQUIRED';end if;
 if x.post_kind='COMPONENT'then
  perform cp7_credit.validate_component(x.component_id);
  select *into strict c from cp7_credit.recognition_components where id=x.component_id;
  select *into strict q from cp7_credit.component_parts where id=x.part_id and component_id=c.id;
  select h0.*into strict h from cp7_credit.cohorts h0 join cp7_credit.recognition_plans p on p.cohort_id=h0.id where p.id=c.plan_id;
  if p_type<>'CP7_CUSTOMER_CREDIT_RECOGNITION'or p_source<>q.id
   or(x.plan_id,x.source_sale_id,x.source_return_id,x.economic_date,x.transaction_date)is distinct from
    (c.plan_id,h.source_sale_id,h.source_return_id,c.economic_date,c.transaction_date)
   or cp7_credit.native_cent_lines(p_lines)is distinct from cp7_credit.part_lines(q.id)then raise exception 'CP7_CREDIT_COMPONENT_POST_SCOPE_CHANGED';end if;
 else
  perform cp7_credit.assert_return_owner_context(x.source_return_id);
  if p_type<>'SALES_RETURN'or p_source<>x.source_return_id then raise exception 'CP7_CREDIT_RETURN_POST_SCOPE_CHANGED';end if;
 end if;
end $$;

create function cp7_credit.post_component(p_component uuid)returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare c cp7_credit.recognition_components;p cp7_credit.recognition_plans;h cp7_credit.cohorts;
 j uuid;lines jsonb;actual erp.journal_entries;ctx cp7_credit.execution_context;
 q cp7_credit.component_parts;receipt jsonb:='[]';
begin
 select *into strict c from cp7_credit.recognition_components where id=p_component;
 select *into strict p from cp7_credit.recognition_plans where id=c.plan_id;
 select *into strict h from cp7_credit.cohorts where id=p.cohort_id;
 perform cp7_credit.assert_owner_context(p.id);
 -- The owning request envelope returns cached committed receipts before this
-- writer. Never repost a component UUID, even after its journal was reversed.
 if exists(select 1 from cp7_credit.component_journals jj join cp7_credit.component_parts qq on qq.id=jj.part_id where qq.component_id=c.id)then
  raise exception 'CP7_CREDIT_COMPONENT_ALREADY_HAS_HISTORY';end if;
 perform cp7_credit.validate_component(c.id);
 select *into strict ctx from cp7_credit.execution_context where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and plan_id=p.id;
 for q in select *from cp7_credit.component_parts where component_id=c.id order by ordinal loop
  lines:=cp7_credit.part_lines(q.id);
  insert into cp7_credit.posting_scope values(pg_backend_pid(),txid_current(),auth.uid(),ctx.request_id,'COMPONENT',
   c.id,q.id,p.id,h.source_sale_id,h.source_return_id,'CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,
   c.economic_date,c.transaction_date,cp7_credit.native_lines_sha256(lines));
  j:=cp7_credit._post_journal_bound('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,c.economic_date,
   'Kredit retur: pengakuan terikat sumber',lines);
  select *into strict actual from erp.journal_entries where id=j;
  if(actual.source_type,actual.source_id,actual.economic_date,actual.transaction_date,actual.status)is distinct from
   ('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,c.economic_date,c.transaction_date,'POSTED')then
   raise exception 'CP7_CREDIT_POSTED_PAIR_CHANGED';end if;
  insert into cp7_credit.component_journals values(q.id,j,c.economic_date,c.transaction_date,
   cp7_credit.native_lines_sha256(lines),statement_timestamp());
  if p.plan_kind='ADJUSTMENT'then perform cp7_credit.seal_source_operation_part_v1(q.id);end if;
  receipt:=receipt||jsonb_build_array(jsonb_build_object('part_id',q.id,'journal_id',j));
  delete from cp7_credit.posting_scope where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 end loop;
 perform cp7_credit.assert_owner_context(p.id);
 return jsonb_build_object('component_id',c.id,'parts',receipt);
end $$;

create function cp7_credit.source_inverse_proof_v1(
 p_before jsonb,p_actual jsonb,p_action text,p_source uuid
)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare original jsonb;inverse jsonb;row jsonb;old_row jsonb;expected jsonb;
 old_event jsonb;actual_event jsonb;old_source jsonb;new_source jsonb;
 original_id uuid;inverse_id uuid;original_header erp.journal_entries;inverse_header erp.journal_entries;
 old_payment erp.sales_payments;new_payment erp.sales_payments;fact erp.sales_payment_posting_facts;
 reversal_fact erp.sales_payment_reversal_facts;fact_json jsonb;reversal_json jsonb;
 original_movements jsonb:='[]';new_movements jsonb:='[]';movement jsonb;back jsonb;
 selected_items jsonb;item jsonb;lot jsonb;new_lot jsonb;balance jsonb;new_balance jsonb;
 key text;source_type text;source_key text;n integer;closed date;lawful date;delta numeric;
 sale_id uuid;ar_account uuid;old_facts jsonb;after_facts jsonb;proof jsonb;
begin
 if p_action is null or p_action not in('RETURN_REVERSE','PAYMENT_REVERSE')or p_source is null then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTION_REQUIRED';end if;
 if jsonb_typeof(p_before)is distinct from'object'or jsonb_typeof(p_actual)is distinct from'object'
  or not p_before?&array['sale','items','allocations','payments','payment_posting_facts','payment_reversal_facts',
   'returns','return_items','base_events','journals','advance_links','fg_lots','hpp_versions','stock_movements',
   'inventory_balances','opening_hpp_states','opening_hpp_corrections','po_hpp_states','hpp_accounts',
   'period_snapshot','nonpo_hpp_events','po_hpp_events','hpp_journals']
  or not p_actual?&array['sale','items','allocations','payments','payment_posting_facts','payment_reversal_facts',
   'returns','return_items','base_events','journals','advance_links','fg_lots','hpp_versions','stock_movements',
   'inventory_balances','opening_hpp_states','opening_hpp_corrections','po_hpp_states','hpp_accounts',
   'period_snapshot','nonpo_hpp_events','po_hpp_events','hpp_journals']then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SNAPSHOT_INCOMPLETE';end if;
 sale_id:=(p_before#>>'{sale,id}')::uuid;
 if sale_id is null or p_actual#>>'{sale,id}'is distinct from sale_id::text
  or p_before->'sale'-array['status','row_version','updated_at']is distinct from
     p_actual->'sale'-array['status','row_version','updated_at']then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SALE_IDENTITY_CHANGED';end if;
 -- The exact bounded hook is BEFORE Native's only sale-header UPDATE.
 -- NATIVE_TRIGGER_TRACE records no child-parent touch and the assembler must
 -- verify that composed trigger set. A shifted hook cannot silently qualify.
 if p_before->'sale'is distinct from p_actual->'sale'then
  raise exception 'CP7_CREDIT_SOURCE_HEADER_CHANGED_BEFORE_NATIVE_E';end if;
 foreach key in array array['items','allocations','return_items','payment_posting_facts','advance_links',
  'hpp_versions','opening_hpp_corrections','hpp_accounts','period_snapshot','nonpo_hpp_events','po_hpp_events']loop
  if p_actual->key is distinct from p_before->key then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PRESERVED_FACT_CHANGED: %',key;end if;
 end loop;
 -- FIRST bounded vertical. These are pre-effect guards too, not a promise
 -- that a later adapter can adopt PO/recost/conversion synchronization.
 if p_before->'advance_links'<>'[]'::jsonb
  or exists(select 1 from jsonb_array_elements(p_before->'payments')x where
   x->>'cash_account_id'is null or x->>'payment_method'='OPENING_ADVANCE')then
  raise exception 'CP7_CREDIT_SOURCE_ADVANCE_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from jsonb_array_elements(p_before->'fg_lots')x where x->>'po_id'is not null)
  or p_before->'po_hpp_states'<>'[]'::jsonb then
  raise exception 'CP7_CREDIT_SOURCE_PO_HPP_INVERSE_UNQUALIFIED';end if;
 if p_before->'opening_hpp_corrections'<>'[]'::jsonb
  or exists(select 1 from jsonb_array_elements(p_before->'hpp_versions')x
   group by x->>'lot_id'having count(*)<>1)then
  raise exception 'CP7_CREDIT_SOURCE_RECOST_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from jsonb_array_elements(p_before->'fg_lots')x where x->>'lot_origin'='CONVERSION')then
  raise exception 'CP7_CREDIT_SOURCE_CONVERSION_INVERSE_UNQUALIFIED';end if;

 source_type:=case when p_action='RETURN_REVERSE'then'SALES_RETURN'else'SALES_PAYMENT'end;
 source_key:=case when p_action='RETURN_REVERSE'then'returns'else'payments'end;
 select count(*)into n from jsonb_array_elements(p_before->source_key)x where x->>'id'=p_source::text;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_SOURCE_NOT_UNIQUE';end if;
 select x into strict old_source from jsonb_array_elements(p_before->source_key)x where x->>'id'=p_source::text;
 select x into strict new_source from jsonb_array_elements(p_actual->source_key)x where x->>'id'=p_source::text;
 if old_source->>'status'is distinct from'POSTED'or new_source->>'status'is distinct from'REVERSED'
  or old_source->>'sale_id'is distinct from sale_id::text
  or old_source-'status'is distinct from new_source-'status'then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SOURCE_STATUS_OR_IDENTITY_CHANGED';end if;
 select cp7_credit.source_rows_v1(coalesce(jsonb_agg(case when x->>'id'=p_source::text
  then jsonb_set(x,'{status}','"REVERSED"')else x end),'[]'))into expected
  from jsonb_array_elements(p_before->source_key)x;
 if cp7_credit.source_rows_v1(p_actual->source_key)is distinct from expected then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_UNRELATED_SOURCE_CHANGED';end if;
 key:=case when p_action='RETURN_REVERSE'then'payments'else'returns'end;
 if p_before->key is distinct from p_actual->key then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_OTHER_SOURCE_KIND_CHANGED';end if;

 select count(*)into n from jsonb_array_elements(p_before->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'=source_type
  and x#>>'{immutable_payload,journal,source_id}'=p_source::text;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_JOURNAL_NOT_UNIQUE';end if;
 select x into strict original from jsonb_array_elements(p_before->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'=source_type
  and x#>>'{immutable_payload,journal,source_id}'=p_source::text;
 original_id:=(original->>'id')::uuid;
 original_header:=jsonb_populate_record(null::erp.journal_entries,original#>'{immutable_payload,journal}');
 if original->>'status'is distinct from'POSTED'or original_header.id is distinct from original_id
  or original_header.reversal_of_id is not null then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_BAD_ORIGINAL_JOURNAL';end if;
 if exists(select 1 from jsonb_array_elements(p_before->'journals')x where
  x#>>'{immutable_payload,journal,source_id}'=original_id::text
  or x#>>'{immutable_payload,journal,reversal_of_id}'=original_id::text)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ALREADY_EXISTED';end if;
 select count(*)into n from jsonb_array_elements(p_actual->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'='JOURNAL_REVERSAL'
  and x#>>'{immutable_payload,journal,source_id}'=original_id::text
  and x#>>'{immutable_payload,journal,reversal_of_id}'=original_id::text;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_JOURNAL_NOT_UNIQUE';end if;
 select x into strict inverse from jsonb_array_elements(p_actual->'journals')x where
  x#>>'{immutable_payload,journal,source_type}'='JOURNAL_REVERSAL'
  and x#>>'{immutable_payload,journal,source_id}'=original_id::text
  and x#>>'{immutable_payload,journal,reversal_of_id}'=original_id::text;
 inverse_id:=(inverse->>'id')::uuid;
 inverse_header:=jsonb_populate_record(null::erp.journal_entries,inverse#>'{immutable_payload,journal}');
 if inverse->>'status'is distinct from'POSTED'or inverse_id is null or inverse_header.id is distinct from inverse_id
  or inverse_id=original_id then raise exception 'CP7_CREDIT_SOURCE_INVERSE_BAD_ACTUAL_JOURNAL';end if;
 select cp7_credit.source_rows_v1(coalesce(jsonb_agg(case when x->>'id'=original_id::text
  then jsonb_set(x,'{status}','"REVERSED"')else x end),'[]')||jsonb_build_array(inverse))into expected
  from jsonb_array_elements(p_before->'journals')x;
 if cp7_credit.source_rows_v1(p_actual->'journals')is distinct from expected then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_PAYLOAD_OR_JOURNAL_SET_CHANGED';end if;
 for row in select x from jsonb_array_elements(p_actual->'journals')x loop
  if cp7_credit.materialized_journal_payload((row->>'id')::uuid)is distinct from row->'immutable_payload'then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_IMMUTABLE_JOURNAL_CHANGED';end if;
 end loop;
 if cp7_credit.source_inverse_vector_v1(inverse#>'{immutable_payload,lines}')is distinct from
    cp7_credit.source_inverse_vector_v1(original#>'{immutable_payload,lines}',true)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_SIGNED_VECTOR_OR_DIMENSIONS_CHANGED';end if;
 if not exists(select 1 from jsonb_array_elements(inverse#>'{immutable_payload,lines}')x having
  sum((x->>'debit')::numeric)=sum((x->>'credit')::numeric)and sum((x->>'debit')::numeric)>0)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_UNBALANCED';end if;
 closed:=(p_before#>>'{period_snapshot,closed_through}')::date;
 lawful:=case when closed is not null and inverse_header.economic_date<=closed
  then greatest(inverse_header.economic_date,closed+1)else inverse_header.economic_date end;
 if inverse_header.economic_date is null or inverse_header.transaction_date is null or inverse_header.posting_at is null
  or inverse_header.economic_date is distinct from(inverse_header.posting_at at time zone'Asia/Jakarta')::date
  or inverse_header.transaction_date is distinct from lawful
  or inverse_header.economic_date<original_header.economic_date or inverse_header.posting_at<original_header.posting_at then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_DATE_PAIR_INVALID';end if;
 -- Historical period proof uses the captured resolver input, never today's
 -- control row. The Native inverse's economic day equals its actual posting day.
 select x into strict old_event from jsonb_array_elements(p_before->'base_events')x
  where x->>'id'='journal:'||original_id::text;
 select x into strict actual_event from jsonb_array_elements(p_actual->'base_events')x
  where x->>'id'='journal:'||inverse_id::text;
 select count(distinct c.ar_account_id),min(c.ar_account_id::text)::uuid into n,ar_account
  from cp7_credit.cohorts c where c.source_sale_id=sale_id;
 if n<>1 then raise exception 'CP7_CREDIT_SOURCE_HISTORICAL_AR_IDENTITY_UNQUALIFIED';end if;
 if old_event->>'kind'is distinct from case when p_action='RETURN_REVERSE'then'NET'else'FUNDING'end
  or actual_event->>'kind'is distinct from old_event->>'kind'
  or(actual_event->>'amount')::numeric is distinct from -(old_event->>'amount')::numeric
  or(actual_event->>'economic_date')::date is distinct from inverse_header.economic_date
  or(actual_event->>'transaction_date')::date is distinct from inverse_header.transaction_date
  or old_event->>'source_sha256'is distinct from ow04_source_proposal.sha(
   ow04_source_proposal.financial_journal_payload(original_id,ar_account))
  or actual_event->>'source_sha256'is distinct from ow04_source_proposal.sha(
   ow04_source_proposal.financial_journal_payload(inverse_id,ar_account))
  or(actual_event->>'amount')::numeric is distinct from(case when p_action='PAYMENT_REVERSE'then -1 else 1 end)*(
   select coalesce(sum((x->>'debit')::numeric-(x->>'credit')::numeric),0)
   from jsonb_array_elements(inverse#>'{immutable_payload,lines}')x where(x->>'account_id')::uuid=ar_account)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_EVENT_CHANGED';end if;
 if cp7_credit.source_rows_v1(p_actual->'base_events')is distinct from
  cp7_credit.source_rows_v1((p_before->'base_events')||jsonb_build_array(actual_event))then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_BASE_EVENT_DELTA_CHANGED';end if;

 if p_action='PAYMENT_REVERSE'then
  old_payment:=jsonb_populate_record(null::erp.sales_payments,old_source);
  new_payment:=jsonb_populate_record(null::erp.sales_payments,new_source);
  select x into strict fact_json from jsonb_array_elements(p_before->'payment_posting_facts')x
   where x->>'payment_id'=p_source::text;
  fact:=jsonb_populate_record(null::erp.sales_payment_posting_facts,fact_json);
  if fact.original_journal_entry_id is distinct from original_id or fact.sale_id is distinct from sale_id
   or fact.customer_id is distinct from(p_before#>>'{sale,customer_id}')::uuid
   or fact.payment_number is distinct from old_payment.payment_number
   or fact.payment_date is distinct from old_payment.payment_date or fact.amount is distinct from old_payment.amount
   or fact.cash_account_id is distinct from old_payment.cash_account_id
   or fact.replaces_payment_id is distinct from old_payment.replaces_payment_id
   or fact.payment_snapshot is distinct from old_source-'status'
   or fact.journal_economic_date is distinct from original_header.economic_date
   or fact.journal_transaction_date is distinct from original_header.transaction_date
   or fact.journal_posting_at is distinct from original_header.posting_at
   or fact.lineage_sha256 is distinct from cp7_credit.pg_jsonb_sha256(jsonb_build_array(
    fact.payment_id,fact.sale_id,fact.customer_id,fact.payment_number,fact.payment_date,fact.amount,
    fact.cash_account_id,fact.original_journal_entry_id,fact.journal_economic_date,fact.journal_transaction_date,
    fact.journal_posting_at,fact.replaces_payment_id,fact.predecessor_reversal_journal_id,fact.payment_snapshot))then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_POSTING_FACT_INVALID';end if;
  if(select to_jsonb(f)from erp.sales_payment_posting_facts f where f.payment_id=p_source)is distinct from fact_json then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_POSTING_FACT_CHANGED';end if;
  if exists(select 1 from jsonb_array_elements(p_before->'payment_reversal_facts')x where x->>'payment_id'=p_source::text)then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_FACT_ALREADY_EXISTED';end if;
  select x into strict reversal_json from jsonb_array_elements(p_actual->'payment_reversal_facts')x
   where x->>'payment_id'=p_source::text;
  reversal_fact:=jsonb_populate_record(null::erp.sales_payment_reversal_facts,reversal_json);
  if(reversal_fact.original_journal_entry_id,reversal_fact.reversal_journal_entry_id,
    reversal_fact.reversal_economic_date,reversal_fact.reversal_transaction_date,reversal_fact.reversal_posting_at)is distinct from
   (original_id,inverse_id,inverse_header.economic_date,inverse_header.transaction_date,inverse_header.posting_at)
   or reversal_fact.lineage_sha256 is distinct from cp7_credit.pg_jsonb_sha256(jsonb_build_array(
    reversal_fact.payment_id,reversal_fact.original_journal_entry_id,reversal_fact.reversal_journal_entry_id,
    reversal_fact.reversal_economic_date,reversal_fact.reversal_transaction_date,reversal_fact.reversal_posting_at))then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_REVERSAL_FACT_INVALID';end if;
  if cp7_credit.source_rows_v1(p_actual->'payment_reversal_facts')is distinct from
    cp7_credit.source_rows_v1((p_before->'payment_reversal_facts')||jsonb_build_array(reversal_json))
   or(select to_jsonb(f)from erp.sales_payment_reversal_facts f where f.payment_id=p_source)is distinct from reversal_json then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_REVERSAL_FACT_SET_CHANGED';end if;
  -- hpp_support includes ALLOCATION.sale = to_jsonb(sales_headers), including
  -- status/version/touch time. It is not a physical immutability predicate.
  -- Preserve every raw physical/HPP fact and full HPP J instead.
  foreach key in array array['fg_lots','stock_movements','inventory_balances','opening_hpp_states',
   'po_hpp_states','hpp_journals']loop
   if p_before->key is distinct from p_actual->key then
    raise exception 'CP7_CREDIT_SOURCE_INVERSE_PAYMENT_CHANGED_PHYSICAL_OR_HPP_FACTS: %',key;end if;
  end loop;
 else
  if p_actual->'payment_reversal_facts'is distinct from p_before->'payment_reversal_facts'then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_RETURN_CHANGED_PAYMENT_FACTS';end if;
  -- Physical bijection and cache arithmetic are delegated to another complete
  -- predicate, supplied in 02. That helper has no authority or work dependency.
  proof:=cp7_credit.source_return_stock_proof_v1(p_before,p_actual,p_source);
 end if;
 -- All relevant HPP journals are an exact before-set plus, for return only,
 -- the actual source inverse. This excludes hidden Native sync/revaluation J.
 expected:=p_before->'hpp_journals';
 if p_action='RETURN_REVERSE'then
  select cp7_credit.source_rows_v1(coalesce(jsonb_agg(case when x->>'id'=original_id::text
   then jsonb_set(x,'{status}','"REVERSED"')else x end),'[]')||case when exists(
    select 1 from jsonb_array_elements(p_before->'hpp_journals')z where z->>'id'=original_id::text)
    then jsonb_build_array(inverse)else'[]'::jsonb end)into expected
   from jsonb_array_elements(p_before->'hpp_journals')x;
 end if;
 if cp7_credit.source_rows_v1(p_actual->'hpp_journals')is distinct from cp7_credit.source_rows_v1(expected)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_UNQUALIFIED_HPP_JOURNAL_EFFECT';end if;
 for row in select x from jsonb_array_elements(p_actual->'hpp_journals')x loop
  if cp7_credit.materialized_journal_payload((row->>'id')::uuid)is distinct from row->'immutable_payload'then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ACTUAL_HPP_JOURNAL_CHANGED';end if;
 end loop;
 return jsonb_build_object('contract_version','ow04.native-source-inverse-proof.v1','action',p_action,
  'source_id',p_source,'sale_id',sale_id,'original_journal_id',original_id,'inverse_journal_id',inverse_id,
  'original_immutable_journal_sha256',cp7_credit.pg_jsonb_sha256(original->'immutable_payload'),
  'inverse_immutable_journal_sha256',cp7_credit.pg_jsonb_sha256(inverse->'immutable_payload'),
  'inverse_signed_vector_sha256',cp7_credit.pg_jsonb_sha256(cp7_credit.source_inverse_vector_v1(inverse#>'{immutable_payload,lines}')),
  'actual_event',actual_event,'actual_event_sha256',cp7_credit.pg_jsonb_sha256(actual_event),
  'actual_pair',jsonb_build_object('economic_date',inverse_header.economic_date,'transaction_date',inverse_header.transaction_date),
  'period_snapshot_sha256',cp7_credit.pg_jsonb_sha256(p_before->'period_snapshot'),
  'before_source_sha256',cp7_credit.pg_jsonb_sha256(p_before),'actual_source_sha256',cp7_credit.pg_jsonb_sha256(p_actual),
  'payment_posting_fact_sha256',case when fact_json is not null then cp7_credit.pg_jsonb_sha256(fact_json)end,
  'payment_reversal_fact_sha256',case when reversal_json is not null then cp7_credit.pg_jsonb_sha256(reversal_json)end,
  'physical_proof',proof,'additional_native_hpp_sync_effects',0);
end $$;

create function cp7_credit.assert_source_materialization_v1(p_operation uuid)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare m cp7_credit.source_operation_materializations_v1;f cp7_credit.financial_materializations;
 sp cp7_credit.source_operation_plans_v1;p cp7_credit.recognition_plans;s cp7_credit.source_operation_part_seals_v1;
 binding text;family jsonb;input_family jsonb;k jsonb;objects jsonb;new_objects jsonb;old_object jsonb;retained_before jsonb;retained_after jsonb;
 side text;support_events jsonb;ar uuid;before_i numeric;
begin
 select *into strict m from cp7_credit.source_operation_materializations_v1 where operation_id=p_operation;
 binding:=cp7_credit.source_operation_binding_sha256_v1(m.operation_id);
 if m.payload_sha256 is distinct from cp7_credit.pg_jsonb_sha256(m.payload)
  or m.actual_manifest_sha256 is distinct from cp7_credit.pg_jsonb_sha256(cp7_credit.source_materialization_manifest_v1(m.operation_id))
  or m.plan_manifest is distinct from cp7_credit.source_stored_plan_manifest_v1(m.operation_id)
  or m.before_ordinal_input is distinct from cp7_credit.source_historical_ordinal_input_v1(m.operation_id,false)
  or m.actual_ordinal_input is distinct from cp7_credit.source_historical_ordinal_input_v1(m.operation_id,true)
  or m.before_financial_profile->'actual_objects'is distinct from cp7_credit.source_historical_objects_v1(m.operation_id)
  or m.before_ordinal_result is distinct from ow04_ordinal_wrapper.reconcile_v1(m.before_ordinal_input)
  or m.actual_ordinal_result is distinct from ow04_ordinal_wrapper.reconcile_v1(m.actual_ordinal_input)
  or not coalesce((m.before_ordinal_result->>'arithmetic_supported')::boolean,false)
  or not coalesce((m.actual_ordinal_result->>'arithmetic_supported')::boolean,false)
  or exists(select 1 from jsonb_array_elements(m.before_ordinal_result->'families')x where(x->>'has_reconciliation_effect')::boolean)
  or m.actual_source_proof is distinct from cp7_credit.source_inverse_proof_v1(m.before_source,m.actual_source,m.action,m.source_id)then
  raise exception 'CP7_CREDIT_SOURCE_MATERIALIZATION_BINDING_CHANGED';end if;
 -- Family registration, retained I and consumers are unchanged by a source
 -- operation. Only actual Native source events may change its target.
 select coalesce(jsonb_agg(x-'events'order by(x->>'ordinal')::bigint),'[]')into retained_before
  from jsonb_array_elements(m.before_ordinal_input->'families')x;
 select coalesce(jsonb_agg(x-'events'order by(x->>'ordinal')::bigint),'[]')into retained_after
  from jsonb_array_elements(m.actual_ordinal_input->'families')x;
 if retained_before is distinct from retained_after or m.actual_ordinal_input->>'family_root_sale_id'<>m.sale_id::text
  or m.before_ordinal_input->>'family_root_sale_id'<>m.sale_id::text then
  raise exception 'CP7_CREDIT_SOURCE_RETAINED_BASELINE_CHANGED';end if;
 select coalesce(sum((e->>'amount')::numeric),0)into before_i
  from jsonb_array_elements(m.before_ordinal_input->'families')f,lateral jsonb_array_elements(f->'retained_recognition')e;
 if m.before_financial_profile->>'actual_objects_sha256'is distinct from cp7_credit.pg_jsonb_sha256(m.before_financial_profile->'actual_objects')
  or(m.before_financial_profile->>'I')::numeric is distinct from before_i
  or(m.before_financial_profile->>'U')::numeric is distinct from 0::numeric
  or(m.before_financial_profile->>'adjustment')::numeric is distinct from -before_i
  or(m.before_financial_profile->>'sale_id',m.before_financial_profile->>'root_sale_id',m.before_financial_profile->>'current_leaf_id')
   is distinct from(m.sale_id::text,m.sale_id::text,m.sale_id::text)then
  raise exception 'CP7_CREDIT_SOURCE_BEFORE_FINANCIAL_PROFILE_CHANGED';end if;
 for sp in select *from cp7_credit.source_operation_plans_v1 where operation_id=m.operation_id order by family_ordinal loop
  select *into strict p from cp7_credit.recognition_plans where id=sp.plan_id;
  select x into strict family from jsonb_array_elements(m.actual_ordinal_result->'families')x
   where x#>>'{registration,family_id}'=sp.family_id::text;
  select x into strict input_family from jsonb_array_elements(m.actual_ordinal_input->'families')x
   where x->>'family_id'=sp.family_id::text;
  k:=cp7_credit.source_adjustment_kernel_v1(family);
  if not coalesce((family->>'has_reconciliation_effect')::boolean,false)or jsonb_array_length(k->'components')=0
   or p.net_amount>=0 or sp.full_family_result is distinct from family or sp.canonical_plan is distinct from k
   or sp.before_retained_events is distinct from input_family->'retained_recognition'
   or sp.before_consumptions is distinct from input_family->'consumptions'
   or family->>'retained_recognition_sha256'is distinct from ow04_pure_kernel.vector_sha256_v1(sp.before_retained_events)
   or family->>'consumptions_sha256'is distinct from ow04_pure_kernel.vector_sha256_v1(sp.before_consumptions)
   or sp.source_binding_sha256 is distinct from binding
   or(p.plan_kind,p.owning_action,p.actor,p.request_id,p.payload_sha256,p.review_sha256,p.family_root_sale_id)is distinct from
    ('ADJUSTMENT',m.action,m.actor,m.request_id,m.payload_sha256,binding,m.sale_id)
   or p.kernel_result is distinct from k or p.net_amount is distinct from(k->>'net_current_k')::numeric
   or p.kernel_version is distinct from k->>'kernel_version'
   or p.before_events is distinct from k->'before_events'or p.added_events is distinct from k->'added_events'
   or p.before_source_sha256 is distinct from k->>'before_source_sha256'
   or p.after_source_sha256 is distinct from k->>'after_source_sha256'
   or p.support_sha256_pg is distinct from cp7_credit.pg_jsonb_sha256(k->'support')
   or p.components_sha256_pg is distinct from cp7_credit.pg_jsonb_sha256(k->'components')
   or p.expected_component_count is distinct from jsonb_array_length(k->'components')
   or p.has_recognition_effect is distinct from(jsonb_array_length(k->'components')>0)
   or exists(select 1 from cp7_credit.plan_dependencies d where d.plan_id=p.id)
   or exists(select 1 from jsonb_array_elements(k->'components')x where(x->>'amount')::numeric>=0)
   or exists(select 1 from cp7_credit.cohorts ch where ch.id=p.cohort_id and ch.family_id<>sp.family_id)
   or not exists(select 1 from cp7_credit.return_families rf where rf.id=sp.family_id and rf.family_root_sale_id=m.sale_id and rf.family_ordinal=sp.family_ordinal)then
   raise exception 'CP7_CREDIT_SOURCE_SIGNED_PLAN_PROVENANCE_CHANGED';end if;
  select ar_account_id into strict ar from cp7_credit.cohorts where id=p.cohort_id;
  foreach side in array array['BEFORE','ADDED']loop
   select coalesce(jsonb_agg(jsonb_build_object('id',s0.event_id,'kind',s0.kind,'amount',cp7_credit.cent_text(s0.amount),
    'economic_date',s0.economic_date::text,'transaction_date',s0.transaction_date::text,'source_sha256',s0.source_sha256)
    order by s0.event_id collate"C"),'[]')into support_events from cp7_credit.plan_support_events s0 where s0.plan_id=p.id and s0.phase=side;
   if support_events is distinct from(case when side='BEFORE'then k->'before_events'else k->'added_events'end)then
    raise exception 'CP7_CREDIT_SOURCE_RETAINED_SUPPORT_VECTOR_CHANGED';end if;
  end loop;
  if exists(select 1 from cp7_credit.plan_support_events s0 where s0.plan_id=p.id and
   (s0.event_id is distinct from'journal:'||s0.journal_id::text
    or s0.source_fact_snapshot is distinct from ow04_source_proposal.financial_journal_payload(s0.journal_id,ar)
    or s0.source_sha256 is distinct from ow04_source_proposal.sha(s0.source_fact_snapshot)))then
   raise exception 'CP7_CREDIT_SOURCE_RETAINED_SUPPORT_FACT_CHANGED';end if;
 end loop;
 if exists(select 1 from cp7_credit.recognition_plans p0 where p0.actor=m.actor and p0.request_id=m.request_id
  and not exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 where sp0.operation_id=m.operation_id and sp0.plan_id=p0.id))
  or exists(select 1 from jsonb_array_elements(m.actual_ordinal_result->'families')x where(x->>'has_reconciliation_effect')::boolean
   and not exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 where sp0.operation_id=m.operation_id and sp0.family_id=(x#>>'{registration,family_id}')::uuid))then
  raise exception 'CP7_CREDIT_SOURCE_SIGNED_PLAN_SET_INCOMPLETE';end if;
 for s in select *from cp7_credit.source_operation_part_seals_v1 where operation_id=m.operation_id loop
  if s.actual_journal_sha256 is distinct from cp7_credit.pg_jsonb_sha256(s.actual_journal)
   or s.actual_journal is distinct from cp7_credit.materialized_journal_payload(s.journal_id)
   or s.source_binding_sha256 is distinct from binding
   or s.journal_link is distinct from(select to_jsonb(j)from cp7_credit.component_journals j where j.part_id=s.part_id and j.journal_id=s.journal_id)
   or not exists(select 1 from cp7_credit.component_parts q join cp7_credit.recognition_components cc on cc.id=q.component_id
    join cp7_credit.source_operation_plans_v1 sp0 on sp0.plan_id=cc.plan_id where q.id=s.part_id and cc.id=s.component_id
     and cc.plan_id=s.plan_id and sp0.operation_id=m.operation_id)
   or not exists(select 1 from erp.journal_entries j where j.id=s.journal_id and j.status='POSTED')
   or exists(select 1 from erp.journal_entries j where j.reversal_of_id=s.journal_id or(j.source_type='JOURNAL_REVERSAL'and j.source_id=s.journal_id))then
   raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_CHANGED';end if;
 end loop;
 if exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 join cp7_credit.recognition_components cc on cc.plan_id=sp0.plan_id
  join cp7_credit.component_parts q on q.component_id=cc.id where sp0.operation_id=m.operation_id
   and not exists(select 1 from cp7_credit.source_operation_part_seals_v1 s0 where s0.operation_id=m.operation_id and s0.part_id=q.id))then
  raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_INCOMPLETE';end if;
 objects:=cp7_credit.current_materialized_objects(m.sale_id,m.sale_id,m.sale_id)->'actual_objects';
 for old_object in select value from jsonb_array_elements(m.before_financial_profile->'actual_objects')loop
  if not exists(select 1 from jsonb_array_elements(objects)x where x=old_object)then
   raise exception 'CP7_CREDIT_SOURCE_OLD_FINANCIAL_HISTORY_CHANGED';end if;
 end loop;
 select coalesce(jsonb_agg(x order by x->>'object_kind'collate"C",x->>'object_id'collate"C"),'[]')into new_objects
  from jsonb_array_elements(objects)x where
   (x->>'object_kind'='PLAN'and exists(select 1 from cp7_credit.source_operation_plans_v1 sp0 where sp0.operation_id=m.operation_id and sp0.plan_id=(x->>'object_id')::uuid))
   or(x->>'object_kind'='COMPONENT'and exists(select 1 from cp7_credit.recognition_components cc join cp7_credit.source_operation_plans_v1 sp0 on sp0.plan_id=cc.plan_id
    where sp0.operation_id=m.operation_id and cc.id=(x->>'object_id')::uuid))
   or(x->>'object_kind'in('PART','PART_JOURNAL')and exists(select 1 from cp7_credit.component_parts q join cp7_credit.recognition_components cc on cc.id=q.component_id
    join cp7_credit.source_operation_plans_v1 sp0 on sp0.plan_id=cc.plan_id where sp0.operation_id=m.operation_id and q.id=(x->>'object_id')::uuid));
 if new_objects is distinct from m.actual_objects or(jsonb_array_length(new_objects)=0)is distinct from(m.financial_marker_id is null)then
  raise exception 'CP7_CREDIT_SOURCE_ACTUAL_OBJECT_SET_CHANGED';end if;
 if m.financial_marker_id is not null then
  select *into strict f from cp7_credit.financial_materializations where id=m.financial_marker_id;
  if(f.root_sale_id,f.actor,f.request_id,f.request_ordinal,f.owning_action,f.payload_sha256,f.source_plan_sha256)is distinct from
   (m.sale_id,m.actor,m.request_id,1,m.action,m.payload_sha256,binding)
   or f.actual_objects is distinct from m.actual_objects or f.actual_objects_sha256 is distinct from cp7_credit.pg_jsonb_sha256(m.actual_objects)
   or exists(select 1 from jsonb_array_elements(m.actual_objects)x where not exists(select 1 from cp7_credit.financial_materialization_objects o
    where o.materialization_id=f.id and o.object_kind=x->>'object_kind'and o.object_id=(x->>'object_id')::uuid and o.fact_sha256=x->>'fact_sha256'))
   or(select count(*)from cp7_credit.financial_materialization_objects where materialization_id=f.id)<>jsonb_array_length(m.actual_objects)then
   raise exception 'CP7_CREDIT_SOURCE_FINANCIAL_MARKER_CHANGED';end if;
 end if;
end $$;

create function cp7_credit.assert_source_adjustment_part_journal_v1(p_part uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare q cp7_credit.component_parts;c cp7_credit.recognition_components;o cp7_credit.component_journals;j erp.journal_entries;
 actual_lines jsonb;
begin
 select *into strict q from cp7_credit.component_parts where id=p_part;
 select *into strict c from cp7_credit.recognition_components where id=q.component_id;
 select *into strict o from cp7_credit.component_journals where part_id=q.id;
 select *into strict j from erp.journal_entries where id=o.journal_id;
 select coalesce(jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,'vendor_id',l.vendor_id,
  'contractor_id',l.contractor_id,'product_id',l.product_id,'po_id',l.po_id,'debit',l.debit,'credit',l.credit)),'[]')into actual_lines
  from erp.journal_lines l where l.journal_entry_id=j.id;
 if(j.source_type,j.source_id,j.reversal_of_id,j.economic_date,j.transaction_date,j.status)is distinct from
   ('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,null::uuid,c.economic_date,c.transaction_date,'POSTED')
  or(o.economic_date,o.transaction_date,o.lines_sha256_pg)is distinct from
   (c.economic_date,c.transaction_date,cp7_credit.native_lines_sha256(cp7_credit.part_lines(q.id)))
  or jsonb_array_length(actual_lines)<>2
  or cp7_credit.initial_line_semantics_v1(actual_lines)is distinct from cp7_credit.initial_line_semantics_v1(cp7_credit.part_lines(q.id))
  or exists(select 1 from erp.journal_entries x where x.reversal_of_id=j.id or(x.source_type='JOURNAL_REVERSAL'and x.source_id=j.id))
  or(select count(*)from erp.journal_entries x where x.source_type='CP7_CUSTOMER_CREDIT_RECOGNITION'and x.source_id=q.id)<>1 then
  raise exception 'CP7_CREDIT_SOURCE_PART_ACTUAL_JOURNAL_CHANGED';end if;
end $$;

create function cp7_credit.assert_source_operation_part_seals_v1(p_operation uuid,p_just_linked uuid default null)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;x cp7_credit.posting_scope;r record;
 v_part cp7_credit.component_parts;v_component cp7_credit.recognition_components;v_cohort cp7_credit.cohorts;
begin
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation;
 if p_just_linked is not null then
  select *into strict x from cp7_credit.posting_scope where backend_pid=w.backend_pid and transaction_id=w.transaction_id and actor=w.actor;
  select *into strict v_part from cp7_credit.component_parts where id=p_just_linked;
  select *into strict v_component from cp7_credit.recognition_components where id=v_part.component_id;
  select ch.*into strict v_cohort from cp7_credit.cohorts ch join cp7_credit.recognition_plans p on p.cohort_id=ch.id where p.id=v_component.plan_id;
  if(x.request_id,x.post_kind,x.plan_id,x.component_id,x.part_id,x.source_sale_id,x.source_return_id,
    x.source_type,x.source_id,x.economic_date,x.transaction_date,x.lines_sha256_pg)is distinct from
   (w.request_id,'COMPONENT',v_component.plan_id,v_component.id,v_part.id,v_cohort.source_sale_id,v_cohort.source_return_id,
    'CP7_CUSTOMER_CREDIT_RECOGNITION',v_part.id,v_component.economic_date,v_component.transaction_date,cp7_credit.native_lines_sha256(cp7_credit.part_lines(v_part.id)))
   or v_component.plan_id is distinct from w.active_plan_id
   or not exists(select 1 from cp7_credit.source_operation_plans_v1 sp where sp.operation_id=w.operation_id and sp.plan_id=v_component.plan_id)
   or exists(select 1 from cp7_credit.source_operation_part_seals_v1 where part_id=p_just_linked)
   or not exists(select 1 from cp7_credit.component_journals where part_id=p_just_linked)then
   raise exception 'CP7_CREDIT_SOURCE_JUST_LINKED_SCOPE_REQUIRED';end if;
 end if;
 -- Exact link->seal and seal->link; missing or extra sealed identities refuse.
 if exists(select 1 from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components c on c.plan_id=sp.plan_id
  join cp7_credit.component_parts q on q.component_id=c.id join cp7_credit.component_journals o on o.part_id=q.id
  where sp.operation_id=w.operation_id and q.id is distinct from p_just_linked and not exists(
   select 1 from cp7_credit.source_operation_part_seals_v1 z where z.operation_id=w.operation_id and z.plan_id=sp.plan_id
    and z.component_id=c.id and z.part_id=q.id and z.journal_id=o.journal_id))
  or exists(select 1 from cp7_credit.source_operation_part_seals_v1 z where z.operation_id=w.operation_id and not exists(
   select 1 from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components c on c.plan_id=sp.plan_id
    join cp7_credit.component_parts q on q.component_id=c.id join cp7_credit.component_journals o on o.part_id=q.id
    where sp.operation_id=w.operation_id and(sp.plan_id,c.id,q.id,o.journal_id)=(z.plan_id,z.component_id,z.part_id,z.journal_id)))then
  raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_SET_CHANGED';end if;
 for r in select q.id part_id,to_jsonb(o) journal_link,z.actual_journal,z.actual_journal_sha256,z.source_binding_sha256,o.journal_id
  from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components c on c.plan_id=sp.plan_id
  join cp7_credit.component_parts q on q.component_id=c.id left join cp7_credit.component_journals o on o.part_id=q.id
  left join cp7_credit.source_operation_part_seals_v1 z on z.part_id=q.id where sp.operation_id=w.operation_id loop
  -- A Native J without its immutable link is never excluded/ignored as pending.
  if r.journal_id is null then
   if exists(select 1 from erp.journal_entries j where j.source_type='CP7_CUSTOMER_CREDIT_RECOGNITION'and j.source_id=r.part_id)then
    raise exception 'CP7_CREDIT_SOURCE_ORPHAN_PART_JOURNAL';end if;
   continue;
  end if;
  perform cp7_credit.assert_source_adjustment_part_journal_v1(r.part_id);
  if r.part_id is not distinct from p_just_linked then continue;end if;
  if r.journal_link is distinct from(select z.journal_link from cp7_credit.source_operation_part_seals_v1 z where z.part_id=r.part_id)
   or r.actual_journal is distinct from cp7_credit.materialized_journal_payload(r.journal_id)
   or r.actual_journal_sha256 is distinct from cp7_credit.pg_jsonb_sha256(r.actual_journal)
   or r.source_binding_sha256 is distinct from cp7_credit.source_operation_binding_sha256_v1(w.operation_id)then
   raise exception 'CP7_CREDIT_SOURCE_PART_SEAL_CHANGED';end if;
 end loop;
end $$;

create function cp7_credit.seal_source_operation_part_v1(p_part uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare q cp7_credit.component_parts;c cp7_credit.recognition_components;s cp7_credit.source_operation_plans_v1;
 o cp7_credit.component_journals;actual jsonb;
begin
 select *into strict q from cp7_credit.component_parts where id=p_part;
 select *into strict c from cp7_credit.recognition_components where id=q.component_id;
 select *into strict s from cp7_credit.source_operation_plans_v1 where plan_id=c.plan_id;
 perform cp7_credit.assert_source_adjustment_owner_base_v1(c.plan_id);
 perform cp7_credit.assert_source_retained_journals_v1(s.operation_id);
 -- Allows this one just-created link, only under its still-live exact posting
 -- scope. Every other part is checked against its existing immutable seal.
 perform cp7_credit.assert_source_operation_part_seals_v1(s.operation_id,q.id);
 select *into strict o from cp7_credit.component_journals where part_id=q.id;
 actual:=cp7_credit.materialized_journal_payload(o.journal_id);
 insert into cp7_credit.source_operation_part_seals_v1(part_id,operation_id,plan_id,component_id,journal_id,journal_link,
  actual_journal,actual_journal_sha256,source_binding_sha256)
 values(q.id,s.operation_id,c.plan_id,c.id,o.journal_id,to_jsonb(o),actual,cp7_credit.pg_jsonb_sha256(actual),
  cp7_credit.source_operation_binding_sha256_v1(s.operation_id));
 perform cp7_credit.assert_source_adjustment_owner_v1(c.plan_id);
end $$;

create function cp7_credit.source_reconciliation_input_v1(p_sale uuid,p_own_operation uuid default null)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare answer jsonb;family jsonb;families jsonb:='[]';retained jsonb;excluded text[]:='{}';w cp7_credit.source_operation_work_v1;
begin
 answer:=cp7_credit.initial_ordinal_input_v1(p_sale);
 if p_own_operation is null then return answer;end if;
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_own_operation
  and backend_pid=pg_backend_pid()and transaction_id=txid_current()and actor=auth.uid();
 if w.sale_id<>p_sale or w.phase<>'RECONCILING'or w.plan_manifest is null then
  raise exception 'CP7_CREDIT_EXACT_SOURCE_OPERATION_BASELINE_REQUIRED';end if;
 perform cp7_credit.assert_source_operation_plan_set_v1(w.operation_id);
 select coalesce(array_agg('part:'||pp.id::text order by pp.id),'{}')into excluded
  from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_plans p on p.id=sp.plan_id
  join cp7_credit.recognition_components cc on cc.plan_id=p.id join cp7_credit.component_parts pp on pp.component_id=cc.id
  where sp.operation_id=w.operation_id;
 for family in select value from jsonb_array_elements(answer->'families')loop
  select coalesce(jsonb_agg(e order by e->>'id'collate"C"),'[]')into retained
   from jsonb_array_elements(family->'retained_recognition')e where not(e->>'id'=any(excluded));
  families:=families||jsonb_build_array(jsonb_set(family,'{retained_recognition}',retained));
 end loop;
 return jsonb_set(answer,'{families}',families);
end $$;

create function cp7_credit.source_adjustment_kernel_v1(p_family jsonb)returns jsonb
language plpgsql immutable security invoker set search_path=''set TimeZone='UTC'as $$
declare target jsonb:=p_family->'source_target';components jsonb;amount numeric;
begin
 if p_family->>'component_basis'is distinct from'FAMILY_TARGET_MINUS_ALL_SUPPLIED_RETAINED_RECOGNITION'
  or not coalesce((p_family->>'arithmetic_supported')::boolean,false)
  or p_family->>'plan_kind'is distinct from'ADJUSTMENT'then
  raise exception 'CP7_CREDIT_SIGNED_FAMILY_ADJUSTMENT_REQUIRED';end if;
 components:=cp7_credit.source_adjustment_components_v1(p_family);
 select coalesce(sum((x->>'amount')::numeric),0)into amount from jsonb_array_elements(components)x;
 if amount is distinct from(p_family->>'reconciliation_net_current')::numeric then
  raise exception 'CP7_CREDIT_SIGNED_FAMILY_ADJUSTMENT_TOTAL_CHANGED';end if;
 return jsonb_build_object('contract_version','ow04.family-adjustment-plan.v1','kernel_version',target->'kernel_version',
  'before_source_sha256',target->'before_source_sha256','after_source_sha256',target->'after_source_sha256',
  'before_events',target->'before_events','added_events',target->'added_events','support',target->'support',
  'components',components,'net_current_k',cp7_credit.cent_text(amount::cp7_credit.cent_amount),
  'has_recognition_effect',jsonb_array_length(components)>0,'full_family_binding',p_family);
end $$;

create function cp7_credit.source_return_stock_proof_v1(p_before jsonb,p_actual jsonb,p_return uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare selected_items jsonb;originals jsonb:='[]';additions jsonb:='[]';old_move jsonb;back jsonb;
 item jsonb;row jsonb;lot jsonb;now_lot jsonb;balance jsonb;now_balance jsonb;n integer;delta numeric;
begin
 select coalesce(jsonb_agg(x order by x->>'id'),'[]')into selected_items
  from jsonb_array_elements(p_before->'return_items')x where x->>'return_id'=p_return::text;
 if selected_items='[]'::jsonb then raise exception 'CP7_CREDIT_SOURCE_INVERSE_RETURN_ITEMS_MISSING';end if;
 for row in select x from jsonb_array_elements(p_before->'stock_movements')x loop
  if not exists(select 1 from jsonb_array_elements(p_actual->'stock_movements')z where z=row)
   or(select to_jsonb(m)from erp.fg_stock_movements m where m.id=(row->>'id')::uuid)is distinct from row then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_STOCK_CHANGED';end if;
 end loop;
 select coalesce(jsonb_agg(x order by x->>'id'),'[]')into additions
  from jsonb_array_elements(p_actual->'stock_movements')x where not exists(
   select 1 from jsonb_array_elements(p_before->'stock_movements')o where o->>'id'=x->>'id');
 for item in select x from jsonb_array_elements(selected_items)x loop
  select count(*)into n from jsonb_array_elements(p_before->'stock_movements')m
   where m->>'source_type'='SALES_RETURN_ITEM'and m->>'source_id'=item->>'id'
    and m->>'movement_type'='SALE_RETURN'and m->>'reversal_of_id'is null;
  if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_STOCK_NOT_UNIQUE';end if;
  select m into strict old_move from jsonb_array_elements(p_before->'stock_movements')m
   where m->>'source_type'='SALES_RETURN_ITEM'and m->>'source_id'=item->>'id'
    and m->>'movement_type'='SALE_RETURN'and m->>'reversal_of_id'is null;
  if(old_move->>'product_id',old_move->>'lot_id',old_move->>'location_id',old_move->>'quality_grade',
     (old_move->>'qty_signed')::numeric,(old_move->>'unit_hpp_snapshot')::numeric,old_move->>'customer_id')is distinct from
    (item->>'product_id',item->>'lot_id',item->>'location_id',item->>'quality_grade',
     (item->>'qty_pcs')::numeric,(item->>'unit_hpp_snapshot')::numeric,p_before#>>'{sale,customer_id}')
   or exists(select 1 from jsonb_array_elements(p_before->'stock_movements')m where m->>'reversal_of_id'=old_move->>'id')then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_ORIGINAL_STOCK_SOURCE_INVALID';end if;
  select count(*)into n from jsonb_array_elements(additions)m where m->>'reversal_of_id'=old_move->>'id';
  if n<>1 then raise exception 'CP7_CREDIT_SOURCE_INVERSE_STOCK_BIJECTION_REQUIRED';end if;
  select m into strict back from jsonb_array_elements(additions)m where m->>'reversal_of_id'=old_move->>'id';
  if(back->>'movement_type',back->>'source_type',back->>'source_id',back->>'reversal_of_id',
     back->>'product_id',back->>'lot_id',back->>'location_id',back->>'quality_grade',
     (back->>'qty_signed')::numeric,(back->>'unit_hpp_snapshot')::numeric,back->>'customer_id')is distinct from
    ('REVERSAL','FG_MOVEMENT_REVERSAL',old_move->>'id',old_move->>'id',
     old_move->>'product_id',old_move->>'lot_id',old_move->>'location_id',old_move->>'quality_grade',
     -(old_move->>'qty_signed')::numeric,(old_move->>'unit_hpp_snapshot')::numeric,old_move->>'customer_id')
   or(back->>'physical_at')::timestamptz is null
   or(back->>'physical_at')::timestamptz<(old_move->>'physical_at')::timestamptz
   or(back->>'system_created_at')::timestamptz<(old_move->>'system_created_at')::timestamptz
   or(select to_jsonb(m)from erp.fg_stock_movements m where m.id=(back->>'id')::uuid)is distinct from back then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_STOCK_DIMENSIONS_OR_CHRONOLOGY_CHANGED';end if;
  -- Native uses clock_timestamp() for physical reversal, statement_timestamp()
  -- for J. No assertion equates their Jakarta dates across midnight.
  originals:=originals||jsonb_build_array(old_move);
 end loop;
 if jsonb_array_length(additions)<>jsonb_array_length(selected_items)then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_EXTRA_STOCK_EFFECT';end if;
 if jsonb_array_length(p_before->'fg_lots')<>jsonb_array_length(p_actual->'fg_lots')then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_LOT_SET_CHANGED';end if;
 for lot in select x from jsonb_array_elements(p_before->'fg_lots')x loop
  select x into strict now_lot from jsonb_array_elements(p_actual->'fg_lots')x where x->>'id'=lot->>'id';
  select coalesce(sum((m->>'qty_signed')::numeric),0)into delta from jsonb_array_elements(additions)m where m->>'lot_id'=lot->>'id';
  if lot-array['cached_qty_pcs','is_open']is distinct from now_lot-array['cached_qty_pcs','is_open']
   or(now_lot->>'cached_qty_pcs')::numeric is distinct from(lot->>'cached_qty_pcs')::numeric+delta
   or(now_lot->>'is_open')::boolean is distinct from((now_lot->>'cached_qty_pcs')::numeric>0)then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_LOT_CACHE_OR_IDENTITY_CHANGED';end if;
 end loop;
 if jsonb_array_length(p_before->'inventory_balances')<>jsonb_array_length(p_actual->'inventory_balances')then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_INVENTORY_KEY_SET_CHANGED';end if;
 for balance in select x from jsonb_array_elements(p_before->'inventory_balances')x loop
  select x into strict now_balance from jsonb_array_elements(p_actual->'inventory_balances')x where
   (x->>'product_id',x->>'location_id',x->>'quality_grade')=
   (balance->>'product_id',balance->>'location_id',balance->>'quality_grade');
  select coalesce(sum((m->>'qty_signed')::numeric),0)into delta from jsonb_array_elements(additions)m where
   (m->>'product_id',m->>'location_id',m->>'quality_grade')=
   (balance->>'product_id',balance->>'location_id',balance->>'quality_grade');
  if balance-array['cached_qty_pcs','updated_at']is distinct from now_balance-array['cached_qty_pcs','updated_at']
   or(now_balance->>'cached_qty_pcs')::numeric is distinct from(balance->>'cached_qty_pcs')::numeric+delta
   or delta=0 and now_balance is distinct from balance
   or delta<>0 and(now_balance->>'updated_at')::timestamptz<(balance->>'updated_at')::timestamptz then
   raise exception 'CP7_CREDIT_SOURCE_INVERSE_INVENTORY_CACHE_CHANGED';end if;
 end loop;
 -- FIRST vertical: no cost correction or opening-state redistribution is
 -- adopted. It must refuse rather than accept a cache-only discrepancy.
 if p_actual->'opening_hpp_states'is distinct from p_before->'opening_hpp_states'
  or p_actual->'po_hpp_states'is distinct from p_before->'po_hpp_states'then
  raise exception 'CP7_CREDIT_SOURCE_INVERSE_HPP_STATE_EFFECT_UNQUALIFIED';end if;
 return jsonb_build_object('contract_version','ow04.native-return-stock-inverse-proof.v1','return_id',p_return,
  'original_movement_ids',(select jsonb_agg(m->'id'order by m->>'id')from jsonb_array_elements(originals)m),
  'inverse_movement_ids',(select jsonb_agg(m->'id'order by m->>'id')from jsonb_array_elements(additions)m),
  'originals_sha256',cp7_credit.pg_jsonb_sha256(cp7_credit.source_rows_v1(originals)),
  'inverses_sha256',cp7_credit.pg_jsonb_sha256(cp7_credit.source_rows_v1(additions)),
  'before_lot_cache_sha256',cp7_credit.pg_jsonb_sha256(p_before->'fg_lots'),
  'actual_lot_cache_sha256',cp7_credit.pg_jsonb_sha256(p_actual->'fg_lots'),
  'before_inventory_sha256',cp7_credit.pg_jsonb_sha256(p_before->'inventory_balances'),
  'actual_inventory_sha256',cp7_credit.pg_jsonb_sha256(p_actual->'inventory_balances'));
end $$;

create function cp7_credit.source_first_nonpo_hpp_alignment_v1(p_snapshot jsonb)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare product uuid;fg uuid;cogs uuid;expense uuid;income uuid;t jsonb;b jsonb;rows jsonb:='[]';
begin
 select(x->>'account_id')::uuid into strict fg from jsonb_array_elements(p_snapshot#>'{hpp_accounts,mappings}')x where x->>'mapping_key'='FG_INVENTORY';
 select(x->>'account_id')::uuid into strict cogs from jsonb_array_elements(p_snapshot#>'{hpp_accounts,mappings}')x where x->>'mapping_key'='COGS';
 select(x->>'account_id')::uuid into strict expense from jsonb_array_elements(p_snapshot#>'{hpp_accounts,mappings}')x where x->>'mapping_key'='OTHER_EXPENSE';
 select(x->>'account_id')::uuid into strict income from jsonb_array_elements(p_snapshot#>'{hpp_accounts,mappings}')x where x->>'mapping_key'='OTHER_INCOME';
 if exists(select 1 from jsonb_array_elements(p_snapshot->'fg_lots')x where x->>'po_id'is not null)then
  raise exception 'CP7_CREDIT_SOURCE_PO_HPP_INVERSE_UNQUALIFIED';end if;
 for product in select distinct(x->>'product_id')::uuid from jsonb_array_elements(p_snapshot->'fg_lots')x loop
  select to_jsonb(v)into strict t from erp.compute_non_po_product_hpp_targets_v2620f(product)v;
  select jsonb_build_object('hpp_total_cost',q.f+q.c+q.o,'fg_value',q.f,'cogs_value',q.c,'other_out_value',q.o)into b
   from(select coalesce(sum(l.debit-l.credit)filter(where l.account_id=fg),0)f,
    coalesce(sum(l.debit-l.credit)filter(where l.account_id=cogs),0)c,
    coalesce(sum(l.debit-l.credit)filter(where l.account_id in(expense,income)),0)o
    from erp.journal_lines l join erp.journal_entries j on j.id=l.journal_entry_id
    left join erp.journal_entries original on original.id=j.reversal_of_id
    where l.product_id=product and l.po_id is null and j.status in('POSTED','REVERSED')
     and(j.source_type<>'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(j.source_id))
     and(j.source_type<>'JOURNAL_REVERSAL'or original.source_type is distinct from'PRODUCT_CONVERSION'
      or erp.be_nonpo_admitted_v1(original.source_id)))q;
  if t is distinct from b then raise exception 'CP7_CREDIT_SOURCE_NATIVE_HPP_TARGET_BOOK_UNQUALIFIED';end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('product_id',product,'target',t,'book',b));
 end loop;
 return rows;
end $$;

create function cp7_credit.assert_source_actual_v1(p_operation uuid)returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;actual jsonb;proof jsonb;alignment jsonb;
begin
 perform cp7_credit.assert_source_operation_work_v1(p_operation);
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation
  and backend_pid=pg_backend_pid()and transaction_id=txid_current()and actor=auth.uid();
 if w.phase not in('ENTERED','RECONCILING')then raise exception 'CP7_CREDIT_SOURCE_ACTUAL_NATIVE_PHASE_REQUIRED';end if;
 if(w.actual_source is null)<>(w.actual_source_proof is null)
  or w.phase='RECONCILING'and(w.actual_source is null or w.actual_source_proof is null)then
  raise exception 'CP7_CREDIT_SOURCE_RECORDED_ACTUAL_PROOF_REQUIRED';end if;
 actual:=cp7_credit.source_native_snapshot_v1(w.sale_id);
 if w.actual_source is not null and w.actual_source is distinct from actual then
  raise exception 'CP7_CREDIT_SOURCE_SEALED_ACTUAL_SNAPSHOT_CHANGED';end if;
 if actual->'period_snapshot'is distinct from w.period_snapshot then
  raise exception 'CP7_CREDIT_SOURCE_PERIOD_CHANGED';end if;
 proof:=cp7_credit.source_inverse_proof_v1(w.before_source,actual,w.action,w.source_id);
 if w.actual_source_proof is not null and w.actual_source_proof is distinct from proof then
  raise exception 'CP7_CREDIT_SOURCE_RECORDED_ACTUAL_PROOF_CHANGED';end if;
 alignment:=cp7_credit.source_first_nonpo_hpp_alignment_v1(actual);
 if(proof#>>'{actual_pair,transaction_date}')::date is distinct from
   erp.resolve_accounting_transaction_date((proof#>>'{actual_pair,economic_date}')::date)then
  raise exception 'CP7_CREDIT_SOURCE_ACTUAL_LAWFUL_DATE_CHANGED';end if;
 -- Actual source and typed proof are returned together so the caller seals
 -- exactly this read, not a later independent snapshot or client projection.
 return jsonb_build_object('actual_source',actual,'actual_source_proof',proof,'native_hpp_alignment',alignment);
end $$;

create function cp7_credit.source_native_terminal_header_v1(p_native jsonb,p_final jsonb,p_inverse uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare j erp.journal_entries;version_before bigint;version_after bigint;
begin
 select *into strict j from erp.journal_entries where id=p_inverse;
 if j.source_type is distinct from'JOURNAL_REVERSAL'or j.reversal_of_id is null then
  raise exception 'CP7_CREDIT_SOURCE_TERMINAL_ACTUAL_INVERSE_REQUIRED';end if;
 version_before:=(p_native#>>'{sale,row_version}')::bigint;
 version_after:=(p_final#>>'{sale,row_version}')::bigint;
 if p_native->'sale'-array['status','row_version','updated_at']is distinct from
    p_final->'sale'-array['status','row_version','updated_at']
  or version_before is null or version_after is distinct from version_before+1
  or(p_final#>>'{sale,updated_at}')::timestamptz is distinct from j.posting_at then
  raise exception 'CP7_CREDIT_SOURCE_TERMINAL_HEADER_NATIVE_TRIGGER_CHANGED';end if;
 -- Only the opaque support summary is allowed to differ alongside the header:
 -- its source includes full ALLOCATION.sale. All raw HPP/physical/J/source rows
 -- remain exact. Root also repeats the strict Native target/book read here.
 if p_native-array['sale','hpp_support']is distinct from p_final-array['sale','hpp_support']then
  raise exception 'CP7_CREDIT_SOURCE_TERMINAL_UNEXPECTED_NATIVE_TAIL_EFFECT';end if;
 return jsonb_build_object('contract_version','ow04.native-source-terminal-header.v1',
  'sale_id',p_final#>'{sale,id}','before_row_version',version_before,'final_row_version',version_after,
  'final_updated_at',p_final#>'{sale,updated_at}','inverse_journal_id',p_inverse,
  'inverse_posting_at',j.posting_at,'native_header_update_count',1);
end $$;

create function cp7_credit.source_hpp_balances_v1(p_sale uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare g record;b jsonb;t jsonb;answer jsonb:='[]';fg uuid;cogs uuid;expense uuid;income uuid;
begin
 fg:=cp7_credit.account_by_mapping_v1('FG_INVENTORY');cogs:=cp7_credit.account_by_mapping_v1('COGS');
 expense:=cp7_credit.account_by_mapping_v1('OTHER_EXPENSE');income:=cp7_credit.account_by_mapping_v1('OTHER_INCOME');
 for g in select distinct case when l.po_id is null then l.product_id end product_id,l.po_id
  from erp.fg_lots l where l.id=any(cp7_credit.source_hpp_lot_ids_v1(p_sale))order by l.po_id nulls first,product_id loop
  t:=cp7_credit.initial_hpp_targets_v1(g.product_id,g.po_id,'[]',false)->'target';
  if g.po_id is null then
   select jsonb_build_object('fg_value',coalesce(sum(l.debit-l.credit)filter(where l.account_id=fg),0),
    'cogs_value',coalesce(sum(l.debit-l.credit)filter(where l.account_id=cogs),0),
    'other_out_value',coalesce(sum(l.debit-l.credit)filter(where l.account_id in(expense,income)),0))into b
    from erp.journal_lines l join erp.journal_entries j on j.id=l.journal_entry_id left join erp.journal_entries o on o.id=j.reversal_of_id
    where l.product_id=g.product_id and l.po_id is null and j.status in('POSTED','REVERSED')
     and(j.source_type<>'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(j.source_id))
     and(j.source_type<>'JOURNAL_REVERSAL'or o.source_type is distinct from'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(o.source_id));
   b:=b||jsonb_build_object('hpp_total_cost',(b->>'fg_value')::numeric+(b->>'cogs_value')::numeric+(b->>'other_out_value')::numeric);
  else b:=cp7_credit.initial_po_hpp_book_v1(g.po_id,fg,cogs,expense,income);end if;
  answer:=answer||jsonb_build_array(jsonb_build_object('product_id',g.product_id,'po_id',g.po_id,'target',t,'book',b));
 end loop;
 return answer;
end $$;

create function cp7_credit.assert_source_operation_work_v1(p_operation uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;q cp7_sales.requests;
begin
 if current_setting('transaction_isolation')<>'read committed'or auth.uid()is null or auth.jwt()->>'role'is distinct from'authenticated'then
  raise exception using errcode='42501',message='CP7_CREDIT_SOURCE_CURRENT_ACTOR_REQUIRED';end if;
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation
  and backend_pid=pg_backend_pid()and transaction_id=txid_current()and actor=auth.uid();
 perform cp7_credit.assert_only_own_sales_source_context_v1(w.sale_id,w.action);
 select *into strict q from cp7_sales.requests where actor=w.actor and request_id=w.request_id;
 if q.response is not null or(q.action,q.payload,q.expected_version)is distinct from(w.action,w.payload,w.expected_version)
  or w.payload_sha256 is distinct from cp7_credit.pg_jsonb_sha256(w.payload)
  or(w.payload->>'sale_id')::uuid<>w.sale_id
  or(w.payload->>case when w.action='RETURN_REVERSE'then'return_id'else'payment_id'end)::uuid<>w.source_id then
  raise exception 'CP7_CREDIT_SOURCE_OWN_PENDING_REQUEST_REQUIRED';end if;
 if cp7_sales.command_access(w.action)is distinct from w.authority_snapshot then
  raise exception using errcode='42501',message='CP7_CREDIT_SOURCE_ACCESS_CHANGED';end if;
 if(select to_jsonb(c)from erp.accounting_period_control c where singleton_id=1)is distinct from w.period_snapshot then
  raise exception 'CP7_CREDIT_SOURCE_PERIOD_CHANGED';end if;
 if exists(select 1 from jsonb_array_elements(w.account_facts)x where
   (select to_jsonb(a)from erp.chart_accounts a where a.id=(x->>'id')::uuid)is distinct from x)
  or exists(select 1 from cp7_credit.initial_return_work where backend_pid=w.backend_pid and transaction_id=w.transaction_id)
  or exists(select 1 from cp7_credit.return_command_scope where backend_pid=w.backend_pid and transaction_id=w.transaction_id)then
  raise exception 'CP7_CREDIT_SOURCE_ACCOUNT_OR_NESTED_OPERATION_CHANGED';end if;
end $$;

create function cp7_credit.source_request_enter_v1(p_action text,p_payload jsonb,p_request uuid,p_expected text)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare sale uuid:=(p_payload->>'sale_id')::uuid;v_source_id uuid;q cp7_sales.requests;src jsonb;
 before_input jsonb;before_result jsonb;profile jsonb;accounts jsonb;period jsonb;authority jsonb;blocked jsonb;
 op uuid:=gen_random_uuid();prior_op uuid;op_ordinal bigint;lot_ids uuid[];fresh_lot_ids uuid[];hpp_ids uuid[];fresh_hpp_ids uuid[];
begin
 if p_action not in('RETURN_REVERSE','PAYMENT_REVERSE')or p_action is null then raise exception 'CP7_CREDIT_SOURCE_ACTION_UNIMPLEMENTED';end if;
 if not exists(select 1 from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=sale)
  and not exists(select 1 from cp7_credit.consumption_events where event_kind='APPLY'and target_sale_id=sale)then return;end if;
 if auth.uid()is null or auth.jwt()->>'role'is distinct from'authenticated'or current_setting('transaction_isolation')<>'read committed'then
  raise exception using errcode='42501',message='CP7_CREDIT_SOURCE_CURRENT_ACTOR_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 perform cp7_credit.assert_only_own_sales_source_context_v1(sale,p_action);
 authority:=cp7_sales.command_access(p_action);
 select *into strict q from cp7_sales.requests where actor=auth.uid()and request_id=p_request;
 if q.response is not null or(q.action,q.payload,q.expected_version)is distinct from(p_action,p_payload,p_expected)then
  raise exception 'CP7_CREDIT_SOURCE_OWN_PENDING_REQUEST_REQUIRED';end if;
 if exists(select 1 from cp7_credit.source_operation_work_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())
  or exists(select 1 from cp7_credit.execution_context where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
  raise exception 'CP7_CREDIT_SOURCE_NESTED_OPERATION';end if;
 v_source_id:=(p_payload->>case when p_action='RETURN_REVERSE'then'return_id'else'payment_id'end)::uuid;
 if p_action='RETURN_REVERSE'then
  if not exists(select 1 from erp.sales_returns where id=v_source_id and sale_id=sale and status='POSTED')then
   raise exception 'CP7_CREDIT_SOURCE_ACTUAL_RETURN_REQUIRED';end if;
 else
  if not exists(select 1 from erp.sales_payments where id=v_source_id and sale_id=sale and status='POSTED')then
   raise exception 'CP7_CREDIT_SOURCE_ACTUAL_PAYMENT_REQUIRED';end if;
  if exists(select 1 from erp.sales_payments where id=v_source_id and(cash_account_id is null or payment_method='OPENING_ADVANCE'))then
   raise exception 'CP7_CREDIT_SOURCE_ADVANCE_INVERSE_UNQUALIFIED';end if;
 end if;
 src:=ow04_source_proposal.locked_source_family(sale);
 if src->>'source_status'is distinct from'BASE_COLLECTED'or src#>>'{family,current_leaf_id}'is distinct from sale::text
  or src#>>'{family,root_sale_id}'is distinct from sale::text then
  raise exception 'CP7_CREDIT_SOURCE_SIMPLE_NATIVE_FAMILY_REQUIRED';end if;
 perform cp7_credit.assert_simple_native_base_v1(sale);
 -- First bounded adapter cannot adopt Native's global conversion expansion.
 -- Refuse before effects until that entire graph has an owning lock/proof.
 if exists(select 1 from erp.be_conversion_sources_v1 s
  join erp.fg_lots l on l.id=s.source_lot_id where l.po_id is null)then
  raise exception 'CP7_CREDIT_SOURCE_GLOBAL_HPP_GRAPH_UNQUALIFIED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('event_id',e.id,'cohort_id',e.cohort_id,'event_kind',e.event_kind,
  'journal_id',e.journal_id,'source_sale_id',c.source_sale_id,'source_return_id',c.source_return_id)order by e.id),'[]')into blocked
  from cp7_credit.consumption_events e join cp7_credit.cohorts c on c.id=e.cohort_id
  join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=sale or e.target_sale_id=sale;
 if jsonb_array_length(blocked)>0 then
  raise exception 'CP7_CREDIT_SOURCE_CONSUMERS_REQUIRE_UNDO'using detail=blocked::text;end if;
 if exists(select 1 from erp.initial_import_prepayment_payments l join erp.sales_payments p on p.id=l.payment_id where p.sale_id=sale)
  or exists(select 1 from erp.sales_payments where sale_id=sale and(cash_account_id is null or payment_method='OPENING_ADVANCE'))then
  raise exception 'CP7_CREDIT_SOURCE_ADVANCE_INVERSE_UNQUALIFIED';end if;
 if p_action='RETURN_REVERSE'then
  perform 1 from erp.locations where id in(select location_id from erp.sales_return_items where return_id=v_source_id)order by id for share;
  perform 1 from erp.fg_inventory_balances b where exists(select 1 from erp.sales_return_items i where i.return_id=v_source_id
   and(i.product_id,i.location_id,i.quality_grade)=(b.product_id,b.location_id,b.quality_grade))
   order by b.product_id,b.location_id,b.quality_grade for update;
  perform 1 from erp.fg_stock_movements m where m.source_type='SALES_RETURN_ITEM'
   and exists(select 1 from erp.sales_return_items i where i.id=m.source_id and i.return_id=v_source_id)order by m.id for update;
 end if;
 lot_ids:=cp7_credit.source_hpp_lot_ids_v1(sale);
 select coalesce(array_agg(id order by id),'{}')into hpp_ids from erp.hpp_versions where lot_id=any(lot_ids);
 perform 1 from erp.fg_lots where id=any(lot_ids)order by id for update;
 perform 1 from erp.hpp_versions where id=any(hpp_ids)order by id for share;
 select coalesce(array_agg(id order by id),'{}')into fresh_hpp_ids from erp.hpp_versions where lot_id=any(lot_ids);
 if hpp_ids is distinct from fresh_hpp_ids then raise exception 'CP7_CREDIT_SOURCE_HPP_LOCK_SET_CHANGED';end if;
 perform 1 from erp.opening_lot_hpp_gl_state where lot_id=any(lot_ids)order by lot_id for update;
 perform 1 from erp.opening_hpp_corrections where lot_id=any(lot_ids)order by id for share;
 perform 1 from erp.po_hpp_gl_state where po_id in(select po_id from erp.fg_lots where id=any(lot_ids))order by po_id for update;
 fresh_lot_ids:=cp7_credit.source_hpp_lot_ids_v1(sale);
 select coalesce(array_agg(id order by id),'{}')into fresh_hpp_ids from erp.hpp_versions where lot_id=any(fresh_lot_ids);
 if fresh_lot_ids is distinct from lot_ids or fresh_hpp_ids is distinct from hpp_ids then
  raise exception 'CP7_CREDIT_SOURCE_LOT_LOCK_SET_CHANGED';end if;
 -- Honest first vertical: preserve Native opening/cache/PO/conversion code;
 -- do not enter a class whose complete effects are not qualified yet.
 if exists(select 1 from erp.fg_lots where id=any(lot_ids)and po_id is not null)
  or exists(select 1 from erp.po_hpp_gl_state where po_id in(select po_id from erp.fg_lots where id=any(lot_ids)))then
  raise exception 'CP7_CREDIT_SOURCE_PO_HPP_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from erp.opening_lot_hpp_gl_state where lot_id=any(lot_ids))then
  raise exception 'CP7_CREDIT_SOURCE_OPENING_HPP_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from erp.opening_hpp_corrections where lot_id=any(lot_ids))
  or exists(select 1 from erp.fg_lots l where l.id=any(lot_ids)and
   ((select count(*)from erp.hpp_versions h where h.lot_id=l.id)<>1
    or(select count(*)from erp.hpp_versions h where h.lot_id=l.id and h.is_current)<>1))then
  raise exception 'CP7_CREDIT_SOURCE_RECOST_INVERSE_UNQUALIFIED';end if;
 if exists(select 1 from erp.fg_lots where id=any(lot_ids)and lot_origin='CONVERSION')then
  raise exception 'CP7_CREDIT_SOURCE_CONVERSION_INVERSE_UNQUALIFIED';end if;
 perform 1 from erp.chart_accounts where id in(select c.credit_account_id from cp7_credit.cohorts c
  join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=sale)
  or id in(select c.ar_account_id from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id
   where f.family_root_sale_id=sale)order by id for share;
 select coalesce(jsonb_agg(to_jsonb(a)order by a.id),'[]')into accounts from erp.chart_accounts a where a.id in(
  select c.credit_account_id from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=sale
  union select c.ar_account_id from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=sale);
 before_input:=cp7_credit.source_reconciliation_input_v1(sale);
 before_result:=ow04_ordinal_wrapper.reconcile_v1(before_input);
 if not(before_result->>'arithmetic_supported')::boolean or exists(select 1 from jsonb_array_elements(before_result->'families')f
  where(f->>'has_reconciliation_effect')::boolean)then raise exception 'CP7_CREDIT_SOURCE_BEFORE_PROFILE_UNRECONCILED';end if;
 perform cp7_credit.assert_current_materialized_profile(sale,sale,sale);
 profile:=cp7_credit.inspect_current_materialized_profile(sale,sale,sale);
 select operation_id,operation_ordinal+1 into prior_op,op_ordinal from cp7_credit.source_operation_materializations_v1
  where sale_id=sale order by operation_ordinal desc limit 1;
 if prior_op is null then op_ordinal:=1;
 elsif not exists(select 1 from cp7_credit.source_operation_completions_v1 where operation_id=prior_op)then
  raise exception 'CP7_CREDIT_SOURCE_PREDECESSOR_NOT_COMPLETE';end if;
 perform 1 from erp.accounting_period_control where singleton_id=1 for share;
 select to_jsonb(c)into strict period from erp.accounting_period_control c where singleton_id=1;
 if cp7_sales.command_access(p_action)is distinct from authority then
  raise exception using errcode='42501',message='CP7_CREDIT_SOURCE_ACCESS_CHANGED';end if;
 insert into cp7_credit.source_operation_work_v1(operation_id,operation_ordinal,predecessor_operation_id,backend_pid,transaction_id,actor,request_id,action,sale_id,source_id,
  expected_version,payload,payload_sha256,authority_snapshot,phase,before_source,before_ordinal_input,before_ordinal_result,
  before_financial_profile,account_facts,period_snapshot)
 values(op,op_ordinal,prior_op,pg_backend_pid(),txid_current(),auth.uid(),p_request,p_action,sale,v_source_id,p_expected,p_payload,
  cp7_credit.pg_jsonb_sha256(p_payload),authority,'PREPARED',cp7_credit.source_native_snapshot_v1(sale),before_input,before_result,
  profile,accounts,period);
 perform cp7_credit.assert_source_operation_work_v1(op);
end $$;

create function cp7_credit.source_operation_binding_payload_v1(p_operation uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare live jsonb;saved jsonb;answer jsonb;other jsonb;
 fields text[]:=array['operation_id','operation_ordinal','predecessor_operation_id','backend_pid','transaction_id',
  'actor','request_id','action','sale_id','source_id','expected_version','payload','payload_sha256','authority_snapshot',
  'before_source','before_ordinal_input','before_ordinal_result','before_financial_profile','account_facts','period_snapshot',
  'actual_source','actual_source_proof','actual_ordinal_input','actual_ordinal_result','plan_manifest'];
begin
 select to_jsonb(w)into live from cp7_credit.source_operation_work_v1 w where operation_id=p_operation;
 select to_jsonb(m)into saved from cp7_credit.source_operation_materializations_v1 m where operation_id=p_operation;
 if live is null and saved is null then raise exception 'CP7_CREDIT_SOURCE_OPERATION_BINDING_ABSENT';end if;
 select jsonb_object_agg(key,value)into answer from jsonb_each(coalesce(saved,live))where key=any(fields);
 if(select count(*)from jsonb_object_keys(answer))<>cardinality(fields)
  or exists(select 1 from jsonb_each(answer)where key<>'predecessor_operation_id'and value='null'::jsonb)then
  raise exception 'CP7_CREDIT_SOURCE_OPERATION_BINDING_INCOMPLETE';end if;
 if live is not null and saved is not null then
  select jsonb_object_agg(key,value)into other from jsonb_each(live)where key=any(fields);
  if other is distinct from answer then raise exception 'CP7_CREDIT_SOURCE_OPERATION_SAVED_BINDING_CHANGED';end if;
 end if;
 return jsonb_build_object('contract_version','ow04.source-operation-input-binding.v1','operation',answer);
end $$;

create function cp7_credit.source_historical_plan_ids_v1(p_operation uuid)returns uuid[]
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare op jsonb;answer uuid[];
begin
 op:=cp7_credit.source_operation_binding_payload_v1(p_operation)->'operation';
 select coalesce(array_agg(p.id order by p.id),'{}')into answer from cp7_credit.recognition_plans p
  join cp7_credit.cohorts c on c.id=p.cohort_id where c.source_sale_id=(op->>'sale_id')::uuid
   and exists(select 1 from jsonb_array_elements(op#>'{before_source,returns}')r
    where r->>'id'=c.source_return_id::text and r->>'status'in('POSTED','REVERSED'))
   and(p.id=c.initial_plan_id or exists(select 1 from cp7_credit.source_operation_plans_v1 sp
    join cp7_credit.source_operation_materializations_v1 old on old.operation_id=sp.operation_id
    where sp.plan_id=p.id and old.sale_id=(op->>'sale_id')::uuid and old.operation_ordinal<(op->>'operation_ordinal')::bigint));
 return answer;
end $$;

create function cp7_credit.source_snapshot_base_events_v1(p_snapshot jsonb)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare answer jsonb;ar uuid;sale uuid:=(p_snapshot#>>'{sale,id}')::uuid;row jsonb;
begin
 select distinct c.ar_account_id into strict ar from cp7_credit.cohorts c where c.source_sale_id=sale;
 for row in select value from jsonb_array_elements(p_snapshot->'journals')loop
  if cp7_credit.materialized_journal_payload((row->>'id')::uuid)is distinct from row->'immutable_payload'then
   raise exception 'CP7_CREDIT_SOURCE_HISTORICAL_JOURNAL_CHANGED';end if;
 end loop;
 with recursive roots(id,kind)as(
  select (j->>'id')::uuid,case when j#>>'{immutable_payload,journal,source_type}'='SALES_PAYMENT'then'FUNDING'else'NET'end
   from jsonb_array_elements(p_snapshot->'journals')j where j#>>'{immutable_payload,journal,reversal_of_id}'is null
    and((j#>>'{immutable_payload,journal,source_type}'='SALE'and j#>>'{immutable_payload,journal,source_id}'=sale::text)
     or(j#>>'{immutable_payload,journal,source_type}'='SALES_RETURN'and exists(select 1 from jsonb_array_elements(p_snapshot->'returns')r
      where r->>'id'=j#>>'{immutable_payload,journal,source_id}'and r->>'status'in('POSTED','REVERSED')))
     or(j#>>'{immutable_payload,journal,source_type}'='SALES_PAYMENT'and exists(select 1 from jsonb_array_elements(p_snapshot->'payments')p
      where p->>'id'=j#>>'{immutable_payload,journal,source_id}'and p->>'status'in('POSTED','REVERSED'))))
 ),walk(id,kind)as(
  select *from roots union select (j->>'id')::uuid,parent.kind from walk parent,jsonb_array_elements(p_snapshot->'journals')j
   where j#>>'{immutable_payload,journal,source_type}'='JOURNAL_REVERSAL'
    and j#>>'{immutable_payload,journal,source_id}'=parent.id::text
    and j#>>'{immutable_payload,journal,reversal_of_id}'=parent.id::text
 )select coalesce(jsonb_agg(jsonb_build_object('id','journal:'||w.id::text,'kind',w.kind,
  'amount',cp7_credit.cent_text(((case when w.kind='FUNDING'then-1 else 1 end)*coalesce(
   (select sum(l.debit-l.credit)from erp.journal_lines l where l.journal_entry_id=w.id and l.account_id=ar),0))::cp7_credit.cent_amount),
  'economic_date',j#>>'{immutable_payload,journal,economic_date}','transaction_date',j#>>'{immutable_payload,journal,transaction_date}',
  'source_sha256',ow04_source_proposal.sha(ow04_source_proposal.financial_journal_payload(w.id,ar)))order by w.id::text collate"C"),'[]')into answer
  from walk w join lateral(select x from jsonb_array_elements(p_snapshot->'journals')x where(x->>'id')::uuid=w.id)payload(j)on true;
 if answer is distinct from p_snapshot->'base_events'or jsonb_array_length(answer)<>jsonb_array_length(p_snapshot->'journals')
  or exists(select 1 from jsonb_array_elements(p_snapshot->'journals')j group by j->>'id'having count(*)<>1)then
  raise exception 'CP7_CREDIT_SOURCE_HISTORICAL_BASE_VECTOR_CHANGED';end if;
 return answer;
end $$;

create function cp7_credit.source_historical_ordinal_input_v1(p_operation uuid,p_after boolean)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare op jsonb;snapshot jsonb;f cp7_credit.return_families;families jsonb:='[]';events jsonb;family_events jsonb;
 retained jsonb;all_return_ids text[]:='{}';plans uuid[];sale uuid;
begin
 op:=cp7_credit.source_operation_binding_payload_v1(p_operation)->'operation';sale:=(op->>'sale_id')::uuid;
 snapshot:=case when p_after then op->'actual_source'else op->'before_source'end;
 plans:=cp7_credit.source_historical_plan_ids_v1(p_operation);events:=cp7_credit.source_snapshot_base_events_v1(snapshot);
 for f in select rf.*from cp7_credit.return_families rf where rf.family_root_sale_id=sale
  and exists(select 1 from jsonb_array_elements(op#>'{before_source,returns}')r
   where r->>'id'=rf.first_return_id::text and r->>'status'in('POSTED','REVERSED'))order by rf.family_ordinal loop
  with recursive journals(id)as(
   select (j->>'id')::uuid from jsonb_array_elements(snapshot->'journals')j
    where j#>>'{immutable_payload,journal,source_type}'='SALES_RETURN'
     and j#>>'{immutable_payload,journal,reversal_of_id}'is null
     and exists(select 1 from cp7_credit.return_family_members mm where mm.family_id=f.id
      and mm.return_id=(j#>>'{immutable_payload,journal,source_id}')::uuid)
   union select (child->>'id')::uuid from journals parent,jsonb_array_elements(snapshot->'journals')child
    where child#>>'{immutable_payload,journal,reversal_of_id}'=parent.id::text
     or(child#>>'{immutable_payload,journal,source_type}'='JOURNAL_REVERSAL'
      and child#>>'{immutable_payload,journal,source_id}'=parent.id::text))
  select coalesce(jsonb_agg(x order by x->>'id'collate"C"),'[]')into family_events
   from jsonb_array_elements(events)x where substring(x->>'id'from 9)::uuid in(select id from journals);
  select all_return_ids||coalesce(array_agg(x->>'id'),'{}')into all_return_ids from jsonb_array_elements(family_events)x;
  select coalesce(jsonb_agg(jsonb_build_object('id','part:'||q.id::text,'amount',cp7_credit.cent_text(q.amount),
   'economic_date',j.economic_date::text,'transaction_date',j.transaction_date::text,
   'source_sha256',cp7_credit.pg_jsonb_sha256(jsonb_build_object('part',to_jsonb(q),'journal_link',to_jsonb(j))))order by q.id),'[]')into retained
   from cp7_credit.recognition_plans p join cp7_credit.cohorts c on c.id=p.cohort_id
   join cp7_credit.recognition_components cc on cc.plan_id=p.id join cp7_credit.component_parts q on q.component_id=cc.id
   join cp7_credit.component_journals j on j.part_id=q.id where p.id=any(plans)and c.family_id=f.id;
  if exists(select 1 from cp7_credit.consumption_events e join cp7_credit.cohorts c on c.id=e.cohort_id where c.family_id=f.id)then
   raise exception 'CP7_CREDIT_SOURCE_HISTORICAL_CONSUMER_ADAPTER_UNIMPLEMENTED';end if;
  families:=families||jsonb_build_array(jsonb_build_object('family_id',f.id,'ordinal',f.family_ordinal::text,
   'first_return_id',f.first_return_id,'registration_sha256',f.source_sha256,'events',family_events,
   'retained_recognition',retained,'consumptions','[]'::jsonb));
 end loop;
 select coalesce(jsonb_agg(x order by x->>'id'collate"C"),'[]')into events
  from jsonb_array_elements(events)x where not(x->>'id'=any(all_return_ids));
 return jsonb_build_object('contract_version','ow04.ordinal-input.v1','family_root_sale_id',sale,'base_events',events,'families',families);
end $$;

create function cp7_credit.source_historical_objects_v1(p_operation uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare op jsonb;objects jsonb;plans uuid[];family_ids uuid[];cohort_ids uuid[];component_ids uuid[];part_ids uuid[];member_ids uuid[];answer jsonb;
begin
 op:=cp7_credit.source_operation_binding_payload_v1(p_operation)->'operation';plans:=cp7_credit.source_historical_plan_ids_v1(p_operation);
 select coalesce(array_agg((x->>'family_id')::uuid),'{}')into family_ids
  from jsonb_array_elements(cp7_credit.source_historical_ordinal_input_v1(p_operation,false)->'families')x;
 select coalesce(array_agg(c.id),'{}')into cohort_ids from cp7_credit.cohorts c where c.family_id=any(family_ids)
  and c.initial_plan_id=any(plans);
 select coalesce(array_agg(m.return_id),'{}')into member_ids from cp7_credit.return_family_members m where m.family_id=any(family_ids)
  and exists(select 1 from jsonb_array_elements(op#>'{before_source,returns}')r where r->>'id'=m.return_id::text and r->>'status'in('POSTED','REVERSED'));
 select coalesce(array_agg(c.id),'{}')into component_ids from cp7_credit.recognition_components c where c.plan_id=any(plans);
 select coalesce(array_agg(q.id),'{}')into part_ids from cp7_credit.component_parts q where q.component_id=any(component_ids);
 objects:=cp7_credit.current_materialized_objects((op->>'sale_id')::uuid,(op->>'sale_id')::uuid,(op->>'sale_id')::uuid)->'actual_objects';
 select coalesce(jsonb_agg(x order by x->>'object_kind'collate"C",x->>'object_id'collate"C"),'[]')into answer
  from jsonb_array_elements(objects)x where(x->>'object_kind'='FAMILY'and(x->>'object_id')::uuid=any(family_ids))
   or(x->>'object_kind'='MEMBER'and(x->>'object_id')::uuid=any(member_ids))
   or(x->>'object_kind'='COHORT'and(x->>'object_id')::uuid=any(cohort_ids))
   or(x->>'object_kind'='PLAN'and(x->>'object_id')::uuid=any(plans))
   or(x->>'object_kind'='COMPONENT'and(x->>'object_id')::uuid=any(component_ids))
   or(x->>'object_kind'in('PART','PART_JOURNAL')and(x->>'object_id')::uuid=any(part_ids));
 return answer;
end $$;

create function cp7_credit.assert_reconciled_source_profile_v1(p_sale uuid,p_actual jsonb)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare m cp7_credit.source_operation_materializations_v1;c cp7_credit.source_operation_completions_v1;
 previous uuid;ordinal bigint:=0;last_source jsonb;
begin
 for m in select *from cp7_credit.source_operation_materializations_v1 where sale_id=p_sale order by operation_ordinal loop
  ordinal:=ordinal+1;
  if m.operation_ordinal<>ordinal or m.predecessor_operation_id is distinct from previous then
   raise exception 'CP7_CREDIT_SOURCE_OPERATION_ORDER_INCOMPLETE';end if;
  if previous is not null and cp7_credit.source_semantic_snapshot_v1(m.before_source)
   is distinct from cp7_credit.source_semantic_snapshot_v1(last_source)then
   raise exception 'CP7_CREDIT_SOURCE_PREDECESSOR_SOURCE_CHANGED';end if;
  perform cp7_credit.assert_source_materialization_v1(m.operation_id);
  select *into c from cp7_credit.source_operation_completions_v1 where operation_id=m.operation_id;
  if c.operation_id is not null then perform cp7_credit.assert_source_completion_v1(m.operation_id);end if;
  if previous is not null and not exists(select 1 from cp7_credit.source_operation_completions_v1 where operation_id=previous)then
   raise exception 'CP7_CREDIT_SOURCE_PREDECESSOR_NOT_COMPLETE';end if;
  last_source:=coalesce(c.final_native_source,m.actual_source);previous:=m.operation_id;
 end loop;
 if previous is null or cp7_credit.source_document_snapshot_v1(p_sale)
  is distinct from cp7_credit.source_semantic_snapshot_v1(last_source)
  or(p_actual->>'U')::numeric<>0 then raise exception 'CP7_CREDIT_CURRENT_SIGNED_SOURCE_CHANGED';end if;
 -- Actual I is validated/summed by the shared mechanical inspector. The
 -- caller has already recomputed the complete current ordinal result with
 -- all actual signed I and required zero differences at every joint cut.
end $$;

create function cp7_credit.source_adjustment_fresh_v1(p_operation uuid)returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;inp jsonb;fresh jsonb;f jsonb;fi jsonb;s cp7_credit.source_operation_plans_v1;
 expected_families uuid[];actual_families uuid[];blocked jsonb;
begin
 perform cp7_credit.assert_source_operation_work_v1(p_operation);
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation;
 if w.phase<>'RECONCILING'then raise exception 'CP7_CREDIT_SOURCE_RECONCILING_REQUIRED';end if;
 perform cp7_credit.assert_source_operation_plan_set_v1(w.operation_id);
 -- Root-owned exact B->N verifier: actual inverse/source/date, physical/HPP
 -- allowed delta, preserved immutable originals. This is NOT a boolean stub.
 perform cp7_credit.assert_source_actual_v1(w.operation_id);
 if cp7_credit.source_native_snapshot_v1(w.sale_id)is distinct from w.actual_source then
  raise exception 'CP7_CREDIT_SOURCE_NATIVE_BOUNDARY_CHANGED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('event_id',e.id,'cohort_id',e.cohort_id,'event_kind',e.event_kind,
  'journal_id',e.journal_id,'source_sale_id',c.source_sale_id,'source_return_id',c.source_return_id)order by e.id),'[]')into blocked
  from cp7_credit.consumption_events e join cp7_credit.cohorts c on c.id=e.cohort_id
  join cp7_credit.return_families rf on rf.id=c.family_id where rf.family_root_sale_id=w.sale_id or e.target_sale_id=w.sale_id;
 if jsonb_array_length(blocked)>0 then raise exception 'CP7_CREDIT_SOURCE_CONSUMERS_REQUIRE_UNDO'using detail=blocked::text;end if;
 -- The existing reader has a one-way check. It is safe here only AFTER the
 -- stronger exact-set proof above. It removes ALL own part IDs together.
 inp:=cp7_credit.source_reconciliation_input_v1(w.sale_id,w.operation_id);
 if inp is distinct from w.actual_ordinal_input then raise exception 'CP7_CREDIT_SOURCE_RETAINED_BASELINE_CHANGED';end if;
 fresh:=ow04_ordinal_wrapper.reconcile_v1(inp);
 if fresh is distinct from w.actual_ordinal_result or not(fresh->>'arithmetic_supported')::boolean then
  raise exception 'CP7_CREDIT_SOURCE_ORDINAL_RESULT_CHANGED';end if;
 select coalesce(array_agg((x->'registration'->>'family_id')::uuid order by(x->'registration'->>'family_id')::uuid),'{}')into expected_families
  from jsonb_array_elements(fresh->'families')x where(x->>'has_reconciliation_effect')::boolean;
 select coalesce(array_agg(family_id order by family_id),'{}')into actual_families
  from cp7_credit.source_operation_plans_v1 where operation_id=w.operation_id;
 if expected_families is distinct from actual_families then raise exception 'CP7_CREDIT_SOURCE_AFFECTED_FAMILY_SET_CHANGED';end if;
 for f in select value from jsonb_array_elements(fresh->'families')loop
  -- Reject one unsupported family atom even if the invoice/global net looks safe.
  if coalesce((f->>'needs_cohort_configuration')::boolean,false)
   or exists(select 1 from jsonb_array_elements(f->'reconciliation_components')a where(a->>'amount')::numeric>=0)then
   raise exception 'CP7_CREDIT_SOURCE_RECONCILIATION_REVIEW_REQUIRED';end if;
  if not(f->>'has_reconciliation_effect')::boolean then continue;end if;
  if f->>'plan_kind'<>'ADJUSTMENT'then raise exception 'CP7_CREDIT_SOURCE_RECONCILIATION_REVIEW_REQUIRED';end if;
  select *into strict s from cp7_credit.source_operation_plans_v1 where operation_id=w.operation_id
   and family_id=(f->'registration'->>'family_id')::uuid;
  select x into strict fi from jsonb_array_elements(inp->'families')x where x->>'family_id'=s.family_id::text;
  if s.full_family_result is distinct from f or s.canonical_plan is distinct from cp7_credit.source_adjustment_kernel_v1(f)
   or s.before_retained_events is distinct from fi->'retained_recognition'
   or s.before_consumptions is distinct from fi->'consumptions'
   or jsonb_array_length(fi->'consumptions')<>0
   or not exists(select 1 from cp7_credit.recognition_plans p join cp7_credit.cohorts c on c.id=p.cohort_id
    where p.id=s.plan_id and c.family_id=s.family_id and c.initial_mode='CREDIT'
     and exists(select 1 from jsonb_array_elements(w.before_financial_profile->'actual_objects')o
      where o->>'object_kind'='COHORT'and(o->>'object_id')::uuid=c.id))then
   raise exception 'CP7_CREDIT_SOURCE_FAMILY_ADJUSTMENT_CHANGED';end if;
 end loop;
 return fresh;
end $$;

create function cp7_credit.assert_source_adjustment_owner_base_v1(p_plan uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare p cp7_credit.recognition_plans;s cp7_credit.source_operation_plans_v1;w cp7_credit.source_operation_work_v1;
 e cp7_credit.execution_context;c cp7_credit.cohorts;a jsonb;
begin
 select *into strict p from cp7_credit.recognition_plans where id=p_plan;
 select *into strict s from cp7_credit.source_operation_plans_v1 where plan_id=p.id;
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=s.operation_id
  and backend_pid=pg_backend_pid()and transaction_id=txid_current()and actor=auth.uid();
 perform cp7_credit.assert_source_operation_work_v1(w.operation_id);
 if w.phase<>'RECONCILING'or w.active_plan_id is distinct from p.id then
  raise exception 'CP7_CREDIT_SOURCE_ACTIVE_PLAN_REQUIRED';end if;
 select *into strict e from cp7_credit.execution_context where backend_pid=w.backend_pid and transaction_id=w.transaction_id and actor=w.actor;
 if(p.plan_kind,p.owning_action,p.actor,p.request_id,p.payload_sha256,p.review_sha256)is distinct from
   ('ADJUSTMENT',w.action,w.actor,w.request_id,w.payload_sha256,cp7_credit.source_operation_binding_sha256_v1(w.operation_id))
  or(e.plan_id,e.request_id,e.owning_action,e.payload_sha256,e.review_sha256,e.authority_snapshot)is distinct from
   (p.id,w.request_id,w.action,w.payload_sha256,p.review_sha256,w.authority_snapshot)then
  raise exception 'CP7_CREDIT_SOURCE_ADJUSTMENT_OWNER_MISMATCH';end if;
 perform cp7_credit.source_adjustment_fresh_v1(w.operation_id);
 select *into strict c from cp7_credit.cohorts where id=p.cohort_id;
 a:=cp7_credit.credit_account_facts_v1(c.credit_account_id);
 -- Actual account eligibility/reconciliation is fresh. Only the account's
 -- immutable master snapshot is compared, since lawful own ADJs add journal IDs.
 if a->'account'is distinct from c.credit_account_snapshot->'account'
  or(select to_jsonb(ar)from erp.chart_accounts ar where ar.id=c.ar_account_id)is distinct from c.source_ar_snapshot
  or cp7_credit.account_by_mapping_v1('AR_CUSTOMER')is distinct from c.ar_account_id
  or c.ar_account_id=c.credit_account_id
  or not exists(select 1 from jsonb_array_elements(w.account_facts)x where(x->>'id')::uuid=c.ar_account_id)
  or not exists(select 1 from jsonb_array_elements(w.account_facts)x where(x->>'id')::uuid=c.credit_account_id)then
  raise exception 'CP7_CREDIT_SOURCE_ADJUSTMENT_ACCOUNT_CHANGED';end if;
end $$;

create function cp7_credit.assert_source_retained_journals_v1(p_operation uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;r record;fact jsonb;
begin
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation;
 for r in select distinct substring(e->>'id'from 6)::uuid part_id from jsonb_array_elements(w.actual_ordinal_input->'families')f,
  lateral jsonb_array_elements(f->'retained_recognition')e loop
  perform cp7_credit.assert_source_adjustment_part_journal_v1(r.part_id);
  select cp7_credit.materialized_fact('PART_JOURNAL',o.part_id,jsonb_build_object('link',to_jsonb(o),
   'actual',cp7_credit.materialized_journal_payload(o.journal_id)))into strict fact
   from cp7_credit.component_journals o where o.part_id=r.part_id;
  if not exists(select 1 from jsonb_array_elements(w.before_financial_profile->'actual_objects')x where x=fact)then
   raise exception 'CP7_CREDIT_SOURCE_RETAINED_ACTUAL_JOURNAL_CHANGED';end if;
 end loop;
end $$;

create function cp7_credit.assert_source_adjustment_owner_v1(p_plan uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare op uuid;
begin
 perform cp7_credit.assert_source_adjustment_owner_base_v1(p_plan);
 select operation_id into strict op from cp7_credit.source_operation_plans_v1 where plan_id=p_plan;
 perform cp7_credit.assert_source_retained_journals_v1(op);
 perform cp7_credit.assert_source_operation_part_seals_v1(op);
 -- Authority/request are rechecked after all fresh reads, without new locks.
 perform cp7_credit.assert_source_operation_work_v1(op);
end $$;

create function cp7_credit.activate_source_adjustment_plan_v1(p_plan uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare s cp7_credit.source_operation_plans_v1;w cp7_credit.source_operation_work_v1;e cp7_credit.execution_context;
begin
 select *into strict s from cp7_credit.source_operation_plans_v1 where plan_id=p_plan;
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=s.operation_id
  and backend_pid=pg_backend_pid()and transaction_id=txid_current()and actor=auth.uid();
 perform cp7_credit.assert_source_operation_work_v1(w.operation_id);
 perform cp7_credit.source_adjustment_fresh_v1(w.operation_id);
 if exists(select 1 from cp7_credit.posting_scope where backend_pid=w.backend_pid and transaction_id=w.transaction_id)then
  raise exception 'CP7_CREDIT_SOURCE_POSTING_SCOPE_NOT_CLEAR';end if;
 select *into e from cp7_credit.execution_context where backend_pid=w.backend_pid and transaction_id=w.transaction_id;
 if found and(e.actor,e.request_id,e.owning_action,e.payload_sha256,e.review_sha256,e.authority_snapshot)is distinct from
  (w.actor,w.request_id,w.action,w.payload_sha256,cp7_credit.source_operation_binding_sha256_v1(w.operation_id),w.authority_snapshot)then
  raise exception 'CP7_CREDIT_SOURCE_EXECUTION_CONTEXT_NOT_OWNED';end if;
 insert into cp7_credit.execution_context(backend_pid,transaction_id,actor,request_id,plan_id,owning_action,payload_sha256,review_sha256,authority_snapshot)
 values(w.backend_pid,w.transaction_id,w.actor,w.request_id,p_plan,w.action,w.payload_sha256,
  cp7_credit.source_operation_binding_sha256_v1(w.operation_id),w.authority_snapshot)
 on conflict(backend_pid,transaction_id)do update set plan_id=excluded.plan_id;
 update cp7_credit.source_operation_work_v1 set active_plan_id=p_plan where operation_id=w.operation_id;
 perform cp7_credit.assert_source_adjustment_owner_v1(p_plan);
end $$;

create function cp7_credit.post_source_adjustment_component_v1(p_component uuid)returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare plan uuid;answer jsonb;
begin
 select plan_id into strict plan from cp7_credit.recognition_components where id=p_component;
 perform cp7_credit.activate_source_adjustment_plan_v1(plan);
 perform cp7_credit.validate_source_adjustment_component_v1(p_component);
 answer:=cp7_credit.post_component(p_component);
 perform cp7_credit.assert_source_adjustment_owner_v1(plan);
 return answer;
end $$;

create function cp7_credit.source_operation_native_enter_v1(p_action text,p_source uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;
begin
 select *into strict w from cp7_credit.source_operation_work_v1 where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and action=p_action and source_id=p_source;
 perform cp7_credit.assert_source_operation_work_v1(w.operation_id);
 if w.phase<>'PREPARED'or w.before_source is distinct from cp7_credit.source_native_snapshot_v1(w.sale_id)
  or w.before_ordinal_input is distinct from cp7_credit.source_reconciliation_input_v1(w.sale_id)then
  raise exception 'CP7_CREDIT_SOURCE_NATIVE_ENTRY_CHANGED';end if;
 update cp7_credit.source_operation_work_v1 set phase='ENTERED'where operation_id=w.operation_id;
end $$;

create function cp7_credit.store_source_adjustments_v1(p_operation uuid,p_actual jsonb)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;inp jsonb;result jsonb;family jsonb;input_family jsonb;k jsonb;
 c cp7_credit.cohorts;manifest jsonb:='[]';components jsonb;parts jsonb;entry jsonb;x jsonb;y jsonb;phase text;
 plan uuid;component uuid;part uuid;request_ordinal integer:=0;component_ordinal integer;part_ordinal bigint;part_count bigint;
 amount numeric;piece numeric;binding text;
begin
 perform cp7_credit.assert_source_operation_work_v1(p_operation);
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation;
 if w.phase<>'ENTERED'or p_actual is distinct from cp7_credit.assert_source_actual_v1(w.operation_id)then
  raise exception 'CP7_CREDIT_SOURCE_ACTUAL_READ_CHANGED';end if;
 inp:=cp7_credit.source_reconciliation_input_v1(w.sale_id);result:=ow04_ordinal_wrapper.reconcile_v1(inp);
 if not coalesce((result->>'arithmetic_supported')::boolean,false)then raise exception 'CP7_CREDIT_SOURCE_ARITHMETIC_UNSUPPORTED';end if;
 for family in select value from jsonb_array_elements(result->'families')loop
  if not(family->>'has_reconciliation_effect')::boolean then continue;end if;
  if family->>'plan_kind'is distinct from'ADJUSTMENT'
   or exists(select 1 from jsonb_array_elements(family->'reconciliation_components')a where(a->>'amount')::numeric>=0)then
   raise exception 'CP7_CREDIT_SOURCE_RECONCILIATION_REVIEW_REQUIRED';end if;
  select ch.*into strict c from cp7_credit.cohorts ch where ch.family_id=(family#>>'{registration,family_id}')::uuid;
  if c.initial_mode<>'CREDIT'or exists(select 1 from cp7_credit.consumption_events where cohort_id=c.id)then
   raise exception 'CP7_CREDIT_SOURCE_CONSUMERS_REQUIRE_UNDO';end if;
  k:=cp7_credit.source_adjustment_kernel_v1(family);plan:=gen_random_uuid();request_ordinal:=request_ordinal+1;
  components:='[]';parts:='[]';component_ordinal:=0;
  for x in select value from jsonb_array_elements(k->'components')loop
   component:=gen_random_uuid();component_ordinal:=component_ordinal+1;amount:=(x->>'amount')::numeric;
   components:=components||jsonb_build_array(jsonb_build_object('id',component,'ordinal',component_ordinal,'component',x));
   part_count:=ceil(abs(amount)/cp7_credit.native_journal_cent_max())::bigint;
   for part_ordinal in 1..part_count loop
    part:=gen_random_uuid();piece:=sign(amount)*least(cp7_credit.native_journal_cent_max(),abs(amount)-(part_ordinal-1)*cp7_credit.native_journal_cent_max());
    parts:=parts||jsonb_build_array(jsonb_build_object('id',part,'component_id',component,'ordinal',part_ordinal,'amount',cp7_credit.cent_text(piece::cp7_credit.cent_amount)));
   end loop;
  end loop;
  manifest:=manifest||jsonb_build_array(jsonb_build_object('plan_id',plan,'family_id',c.family_id,
   'family_ordinal',(family#>>'{registration,ordinal}')::bigint,'cohort_id',c.id,'request_ordinal',request_ordinal,
   'kernel_sha256',cp7_credit.pg_jsonb_sha256(k),'components',components,'parts',parts));
 end loop;
 update cp7_credit.source_operation_work_v1 set phase='RECONCILING',actual_source=p_actual->'actual_source',
  actual_source_proof=p_actual->'actual_source_proof',actual_ordinal_input=inp,actual_ordinal_result=result,plan_manifest=manifest
  where operation_id=w.operation_id;
 binding:=cp7_credit.source_operation_binding_sha256_v1(w.operation_id);
 for entry in select value from jsonb_array_elements(manifest)loop
  select f into strict family from jsonb_array_elements(result->'families')f where f#>>'{registration,family_id}'=entry->>'family_id';
  select f into strict input_family from jsonb_array_elements(inp->'families')f where f->>'family_id'=entry->>'family_id';
  k:=cp7_credit.source_adjustment_kernel_v1(family);plan:=(entry->>'plan_id')::uuid;
  insert into cp7_credit.recognition_plans(id,cohort_id,plan_kind,owning_action,actor,request_id,request_ordinal,payload_sha256,review_sha256,
   family_root_sale_id,before_events,added_events,kernel_result,kernel_version,before_source_sha256,after_source_sha256,support_sha256_pg,
   components_sha256_pg,parts_sha256_pg,net_amount,has_recognition_effect,expected_component_count,expected_part_count)
  values(plan,(entry->>'cohort_id')::uuid,'ADJUSTMENT',w.action,w.actor,w.request_id,(entry->>'request_ordinal')::integer,w.payload_sha256,binding,
   w.sale_id,k->'before_events',k->'added_events',k,k->>'kernel_version',k->>'before_source_sha256',k->>'after_source_sha256',
   cp7_credit.pg_jsonb_sha256(k->'support'),cp7_credit.pg_jsonb_sha256(k->'components'),cp7_credit.pg_jsonb_sha256(entry->'parts'),
   (k->>'net_current_k')::numeric,true,jsonb_array_length(k->'components'),jsonb_array_length(entry->'parts'));
  for x in select value from jsonb_array_elements(entry->'components')loop
   y:=x->'component';
   insert into cp7_credit.recognition_components(id,plan_id,ordinal,economic_date,transaction_date,amount,previous_economic_date,previous_transaction_date,corners,kernel_component,component_sha256_pg)
   values((x->>'id')::uuid,plan,(x->>'ordinal')::integer,(y->>'economic_date')::date,(y->>'transaction_date')::date,(y->>'amount')::numeric,
    (y->>'previous_economic_date')::date,(y->>'previous_transaction_date')::date,y->'corners',y,cp7_credit.pg_jsonb_sha256(y));
  end loop;
  for x in select value from jsonb_array_elements(entry->'parts')loop
   insert into cp7_credit.component_parts(id,component_id,ordinal,amount)
    values((x->>'id')::uuid,(x->>'component_id')::uuid,(x->>'ordinal')::bigint,(x->>'amount')::numeric);
  end loop;
  select *into strict c from cp7_credit.cohorts where id=(entry->>'cohort_id')::uuid;
  foreach phase in array array['BEFORE','ADDED']loop
   for x in select value from jsonb_array_elements(case when phase='BEFORE'then k->'before_events'else k->'added_events'end)loop
    insert into cp7_credit.plan_support_events(plan_id,event_id,phase,kind,amount,economic_date,transaction_date,source_sha256,journal_id,source_fact_snapshot)
    values(plan,x->>'id',phase,x->>'kind',(x->>'amount')::numeric,(x->>'economic_date')::date,(x->>'transaction_date')::date,x->>'source_sha256',
     substring(x->>'id'from 9)::uuid,ow04_source_proposal.financial_journal_payload(substring(x->>'id'from 9)::uuid,c.ar_account_id));
   end loop;
  end loop;
  insert into cp7_credit.source_operation_plans_v1(plan_id,operation_id,family_id,family_ordinal,full_family_result,canonical_plan,
   before_retained_events,before_consumptions,source_binding_sha256)
  values(plan,w.operation_id,(entry->>'family_id')::uuid,(entry->>'family_ordinal')::bigint,family,k,
   input_family->'retained_recognition',input_family->'consumptions',binding);
 end loop;
 perform cp7_credit.assert_source_operation_plan_set_v1(w.operation_id);
 perform cp7_credit.source_adjustment_fresh_v1(w.operation_id);
end $$;

create function cp7_credit.materialize_source_operation_v1(p_operation uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;profile jsonb;objects jsonb;new_objects jsonb;x jsonb;marker uuid;
 binding text;manifest jsonb;manifest_sha text;
begin
 perform cp7_credit.assert_source_operation_work_v1(p_operation);
 select *into strict w from cp7_credit.source_operation_work_v1 where operation_id=p_operation;
 perform cp7_credit.source_adjustment_fresh_v1(w.operation_id);
 perform cp7_credit.assert_source_operation_part_seals_v1(w.operation_id);
 profile:=cp7_credit.current_materialized_objects(w.sale_id,w.sale_id,w.sale_id);objects:=profile->'actual_objects';
 select coalesce(jsonb_agg(obj order by obj->>'object_kind'collate"C",obj->>'object_id'collate"C"),'[]')into new_objects
  from jsonb_array_elements(objects)obj where not exists(select 1 from cp7_credit.financial_materialization_objects old
   where old.object_kind=obj->>'object_kind'and old.object_id=(obj->>'object_id')::uuid);
 binding:=cp7_credit.source_operation_binding_sha256_v1(w.operation_id);
 if jsonb_array_length(new_objects)>0 then
  marker:=gen_random_uuid();
  insert into cp7_credit.financial_materializations(id,root_sale_id,actor,request_id,request_ordinal,owning_action,payload_sha256,
   source_plan_sha256,actual_objects,actual_objects_sha256)
  values(marker,w.sale_id,w.actor,w.request_id,1,w.action,w.payload_sha256,binding,new_objects,cp7_credit.pg_jsonb_sha256(new_objects));
  for x in select value from jsonb_array_elements(new_objects)loop
   insert into cp7_credit.financial_materialization_objects(object_kind,object_id,materialization_id,fact_sha256)
    values(x->>'object_kind',(x->>'object_id')::uuid,marker,x->>'fact_sha256');
  end loop;
 end if;
 manifest:=jsonb_build_object('contract_version','ow04.source-operation-actual-manifest.v1','operation_id',w.operation_id,
  'source_binding_sha256',binding,'financial_marker_id',marker,'actual_objects',new_objects);
 manifest_sha:=cp7_credit.pg_jsonb_sha256(manifest);
 insert into cp7_credit.source_operation_materializations_v1(operation_id,operation_ordinal,predecessor_operation_id,backend_pid,transaction_id,
  actor,request_id,action,sale_id,source_id,expected_version,payload,payload_sha256,authority_snapshot,before_source,before_ordinal_input,
  before_ordinal_result,before_financial_profile,account_facts,period_snapshot,actual_source,actual_source_proof,actual_ordinal_input,
  actual_ordinal_result,plan_manifest,financial_marker_id,actual_objects,actual_manifest_sha256)
 values(w.operation_id,w.operation_ordinal,w.predecessor_operation_id,w.backend_pid,w.transaction_id,w.actor,w.request_id,w.action,w.sale_id,
  w.source_id,w.expected_version,w.payload,w.payload_sha256,w.authority_snapshot,w.before_source,w.before_ordinal_input,w.before_ordinal_result,
  w.before_financial_profile,w.account_facts,w.period_snapshot,w.actual_source,w.actual_source_proof,w.actual_ordinal_input,w.actual_ordinal_result,
  w.plan_manifest,marker,new_objects,manifest_sha);
 update cp7_credit.source_operation_work_v1 set phase='RECONCILED',active_plan_id=null,financial_marker_id=marker,actual_manifest_sha256=manifest_sha
  where operation_id=w.operation_id;
 delete from cp7_credit.execution_context where backend_pid=w.backend_pid and transaction_id=w.transaction_id and actor=w.actor and request_id=w.request_id;
 perform cp7_credit.assert_current_materialized_profile(w.sale_id,w.sale_id,w.sale_id);
end $$;

create function cp7_credit.source_operation_native_reconcile_v1(p_action text,p_source uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;actual jsonb;c record;
begin
 if not cp7_credit.source_operation_owns_v1(p_action,p_source)then return;end if;
 select *into strict w from cp7_credit.source_operation_work_v1 where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and action=p_action and source_id=p_source;
 actual:=cp7_credit.assert_source_actual_v1(w.operation_id);
 perform cp7_credit.store_source_adjustments_v1(w.operation_id,actual);
 for c in select cc.id from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_components cc on cc.plan_id=sp.plan_id
  where sp.operation_id=w.operation_id order by sp.family_ordinal,cc.ordinal loop
  perform cp7_credit.post_source_adjustment_component_v1(c.id);
 end loop;
 perform cp7_credit.materialize_source_operation_v1(w.operation_id);
end $$;

create function cp7_credit.source_operation_native_complete_v1(p_action text,p_source uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;profile jsonb;actual jsonb;manifest jsonb;header_proof jsonb;
begin
 select *into strict w from cp7_credit.source_operation_work_v1 where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and action=p_action and source_id=p_source;
 perform cp7_credit.assert_source_operation_work_v1(w.operation_id);
 if w.phase<>'RECONCILED'then raise exception 'CP7_CREDIT_SOURCE_RECONCILIATION_NOT_COMPLETE';end if;
 actual:=cp7_credit.source_native_snapshot_v1(w.sale_id);
 header_proof:=cp7_credit.source_native_terminal_header_v1(w.actual_source,actual,(w.actual_source_proof->>'inverse_journal_id')::uuid);
 -- The first adapter does not adopt terminal cost/cache revaluations. The
 -- opaque support hash includes the very header metadata proven above;
 -- every raw physical/HPP/source row and complete book vector stays exact.
 if actual-array['sale','hpp_support']is distinct from w.actual_source-array['sale','hpp_support']then
  raise exception 'CP7_CREDIT_SOURCE_TERMINAL_EFFECT_UNQUALIFIED';end if;
 perform cp7_credit.source_first_nonpo_hpp_alignment_v1(actual);
 profile:=cp7_credit.inspect_current_materialized_profile(w.sale_id,w.sale_id,w.sale_id);
 perform cp7_credit.assert_source_final_ar_status_v1(w.sale_id,actual,profile);
 manifest:=jsonb_build_object('contract_version','ow04.source-operation-completion.v1','operation_id',w.operation_id,
  'actual_manifest_sha256',w.actual_manifest_sha256,'final_native_source',actual,'final_profile',profile,'header_proof',header_proof);
 insert into cp7_credit.source_operation_completions_v1(operation_id,final_native_source,final_profile,final_manifest_sha256)
  values(w.operation_id,actual,profile,cp7_credit.pg_jsonb_sha256(manifest));
 update cp7_credit.source_operation_work_v1 set phase='NATIVE_COMPLETE'where operation_id=w.operation_id;
 perform cp7_credit.assert_current_materialized_profile(w.sale_id,w.sale_id,w.sale_id);
end $$;

create function cp7_credit.source_request_finish_v1(p_request uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare w cp7_credit.source_operation_work_v1;c cp7_credit.source_operation_completions_v1;
begin
 select *into w from cp7_credit.source_operation_work_v1 where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and request_id=p_request;
 if not found then
  -- No newly owned source is expected on unchanged EMPTY/nonparticipant paths.
  if exists(select 1 from cp7_credit.source_operation_materializations_v1 where actor=auth.uid()and request_id=p_request)then
   raise exception 'CP7_CREDIT_SOURCE_OWN_WORK_MISSING';end if;
  return;
 end if;
 perform cp7_credit.assert_source_operation_work_v1(w.operation_id);
 select *into strict c from cp7_credit.source_operation_completions_v1 where operation_id=w.operation_id;
 if w.phase<>'NATIVE_COMPLETE'or c.final_native_source is distinct from cp7_credit.source_native_snapshot_v1(w.sale_id)
  or exists(select 1 from cp7_credit.execution_context where backend_pid=w.backend_pid and transaction_id=w.transaction_id)
  or exists(select 1 from cp7_credit.posting_scope where backend_pid=w.backend_pid and transaction_id=w.transaction_id)then
  raise exception 'CP7_CREDIT_SOURCE_NATIVE_TAIL_NOT_COMPLETE';end if;
 perform cp7_credit.assert_current_materialized_profile(w.sale_id,w.sale_id,w.sale_id);
 perform cp7_credit.assert_source_completion_v1(w.operation_id);
 delete from cp7_credit.source_operation_work_v1 where operation_id=w.operation_id;
end $$;

create function cp7_credit.assert_source_final_ar_status_v1(p_sale uuid,p_source jsonb,p_profile jsonb)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare net numeric;paid numeric;raw_ar numeric;ar uuid;current_i numeric;current_u numeric;
begin
 if(p_source#>>'{sale,id}',p_profile->>'sale_id',p_profile->>'root_sale_id',p_profile->>'current_leaf_id')
  is distinct from(p_sale::text,p_sale::text,p_sale::text,p_sale::text)then
  raise exception 'CP7_CREDIT_SOURCE_FINAL_PROFILE_IDENTITY_CHANGED';end if;
 select coalesce(sum((x->>'line_total')::numeric),0)into net from jsonb_array_elements(p_source->'items')x;
 net:=net-(select coalesce(sum((i->>'refund_amount')::numeric),0)from jsonb_array_elements(p_source->'return_items')i
  where exists(select 1 from jsonb_array_elements(p_source->'returns')r where r->>'id'=i->>'return_id'and r->>'status'='POSTED'));
 current_i:=(p_profile->>'I')::numeric;current_u:=(p_profile->>'U')::numeric;
 select coalesce(sum((x->>'amount')::numeric),0)into paid from jsonb_array_elements(p_source->'payments')x where x->>'status'='POSTED';
 paid:=paid+current_u-current_i;
 if net is null or paid is null or current_u is distinct from 0::numeric or net<0 or paid<0 or paid>net
  or p_source#>>'{sale,status}'is distinct from(case when paid=net then'PAID'when paid>0 then'PARTIAL_PAID'else'POSTED'end)then
  raise exception 'CP7_CREDIT_SOURCE_FINAL_AR_OR_STATUS_MISMATCH';end if;
 select distinct c.ar_account_id into strict ar from cp7_credit.cohorts c where c.source_sale_id=p_sale;
 select coalesce(sum(l.debit-l.credit),0)into raw_ar from erp.journal_lines l where l.account_id=ar and l.journal_entry_id in(
  select substring(x->>'id'from 9)::uuid from jsonb_array_elements(p_source->'base_events')x
  union select j.journal_id from cp7_credit.component_journals j join cp7_credit.component_parts q on q.id=j.part_id
   join cp7_credit.recognition_components cc on cc.id=q.component_id join cp7_credit.recognition_plans p on p.id=cc.plan_id
   where p.family_root_sale_id=p_sale and exists(select 1 from jsonb_array_elements(p_profile->'actual_objects')o
    where o->>'object_kind'='PART_JOURNAL'and(o->>'object_id')::uuid=q.id));
 if raw_ar is distinct from net-paid then raise exception 'CP7_CREDIT_SOURCE_FINAL_RAW_AR_MISMATCH';end if;
end $$;

create function cp7_credit.assert_source_completion_v1(p_operation uuid)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare m cp7_credit.source_operation_materializations_v1;c cp7_credit.source_operation_completions_v1;
 objects jsonb;expected_i numeric;
begin
 select *into strict m from cp7_credit.source_operation_materializations_v1 where operation_id=p_operation;
 select *into strict c from cp7_credit.source_operation_completions_v1 where operation_id=p_operation;
 perform cp7_credit.assert_source_materialization_v1(m.operation_id);
 if c.final_manifest_sha256 is distinct from cp7_credit.pg_jsonb_sha256(cp7_credit.source_completion_manifest_v1(m.operation_id))
  or c.final_native_source-array['sale','hpp_support']is distinct from m.actual_source-array['sale','hpp_support']then
  raise exception 'CP7_CREDIT_SOURCE_FINAL_NATIVE_MANIFEST_CHANGED';end if;
 select coalesce(jsonb_agg(x order by x->>'object_kind'collate"C",x->>'object_id'collate"C"),'[]')into objects
  from jsonb_array_elements((m.before_financial_profile->'actual_objects')||m.actual_objects)x;
 expected_i:=(m.before_financial_profile->>'I')::numeric+(select coalesce(sum(p.net_amount),0)
  from cp7_credit.source_operation_plans_v1 sp join cp7_credit.recognition_plans p on p.id=sp.plan_id where sp.operation_id=m.operation_id);
 if c.final_profile->'actual_objects'is distinct from objects
  or c.final_profile->>'actual_objects_sha256'is distinct from cp7_credit.pg_jsonb_sha256(objects)
  or(c.final_profile->>'I')::numeric is distinct from expected_i
  or(c.final_profile->>'U')::numeric is distinct from 0::numeric
  or(c.final_profile->>'adjustment')::numeric is distinct from -expected_i then
  raise exception 'CP7_CREDIT_SOURCE_FINAL_FINANCIAL_PROFILE_CHANGED';end if;
 perform cp7_credit.assert_source_final_ar_status_v1(m.sale_id,c.final_native_source,c.final_profile);
end $$;

create function cp7_credit.assert_source_operation_closed_v1(p_operation uuid)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare m cp7_credit.source_operation_materializations_v1;c cp7_credit.source_operation_completions_v1;
 q cp7_sales.requests;expected jsonb;profile jsonb;
begin
 select *into strict m from cp7_credit.source_operation_materializations_v1 where operation_id=p_operation;
 select *into strict c from cp7_credit.source_operation_completions_v1 where operation_id=m.operation_id;
 select *into strict q from cp7_sales.requests where actor=m.actor and request_id=m.request_id;
 perform cp7_credit.assert_source_completion_v1(m.operation_id);
 expected:=jsonb_build_object('contract_version','cp7.sales-outcome.v1','kind','COMMITTED_OUTCOME','action',m.action,'request_id',m.request_id,
  'sale_id',m.sale_id,'status',c.final_native_source#>>'{sale,status}','row_version',c.final_native_source#>>'{sale,row_version}');
 if m.action='RETURN_REVERSE'then expected:=expected||jsonb_build_object('return_id',m.source_id,'return_status','REVERSED');
 else expected:=expected||jsonb_build_object('payment_id',m.source_id,'payment_status','REVERSED');end if;
 if(q.action,q.payload,q.expected_version,q.response)is distinct from(m.action,m.payload,m.expected_version,expected)
  or exists(select 1 from cp7_credit.source_operation_work_v1 w where w.operation_id=m.operation_id
   or(w.backend_pid,w.transaction_id)=(m.backend_pid,m.transaction_id))
  or exists(select 1 from cp7_credit.execution_context where backend_pid=m.backend_pid and transaction_id=m.transaction_id)
  or exists(select 1 from cp7_credit.posting_scope where backend_pid=m.backend_pid and transaction_id=m.transaction_id)
  or exists(select 1 from cp7_credit.source_mutation_scope where backend_pid=m.backend_pid and transaction_id=m.transaction_id)
  or exists(select 1 from cp7_sales.command_context where backend_pid=m.backend_pid and transaction_id=m.transaction_id)then
  raise exception 'CP7_CREDIT_SOURCE_FINAL_RECEIPT_OR_SCOPE_NOT_CLOSED';end if;
 perform cp7_credit.assert_current_materialized_profile(m.sale_id,m.sale_id,m.sale_id);
 profile:=cp7_credit.inspect_current_materialized_profile(m.sale_id,m.sale_id,m.sale_id);
 perform cp7_credit.assert_source_final_ar_status_v1(m.sale_id,cp7_credit.source_native_snapshot_v1(m.sale_id),profile);
end $$;

create function cp7_credit.enforce_source_operation_closure_v1()returns trigger
language plpgsql security definer set search_path=''set TimeZone='UTC'as $$
begin
 if tg_op='UPDATE'and old.operation_id is distinct from new.operation_id then
  perform cp7_credit.assert_source_operation_closed_v1(old.operation_id);
 end if;
 perform cp7_credit.assert_source_operation_closed_v1(new.operation_id);
 return null;
end $$;

do $lock_history$ declare t text;begin
 foreach t in array array['return_families','return_family_members','cohorts','recognition_plans','plan_support_events',
  'recognition_components','component_parts','component_journals','consumption_events','plan_dependencies']loop
  execute format('alter table cp7_credit.%I enable row level security',t);
  execute format('create policy no_direct_access on cp7_credit.%I for all to public using(false)with check(false)',t);
  execute format('create trigger immutable_row before update or delete on cp7_credit.%I for each row execute function cp7_credit.immutable_fact()',t);
  execute format('create trigger immutable_truncate before truncate on cp7_credit.%I for each statement execute function cp7_credit.immutable_fact()',t);
 end loop;
end $lock_history$;

do $protect_source_operations$declare t text;begin
 foreach t in array array['source_operation_work_v1','source_operation_materializations_v1','source_operation_plans_v1','source_operation_completions_v1','source_operation_part_seals_v1']loop
  execute 'alter table cp7_credit.'||t||' owner to postgres';
  execute 'alter table cp7_credit.'||t||' enable row level security';
  execute 'create policy deny_direct on cp7_credit.'||t||' for all to public using(false)with check(false)';
  execute 'revoke all on cp7_credit.'||t||' from public,anon,authenticated,service_role,cp7_capture,cp7_sales_read,cp7_sales_write';
  if t<>'source_operation_work_v1'then
   execute 'create trigger immutable_row before update or delete on cp7_credit.'||t||' for each row execute function cp7_credit.immutable_fact()';
   execute 'create trigger immutable_truncate before truncate on cp7_credit.'||t||' for each statement execute function cp7_credit.immutable_fact()';
  end if;
 end loop;
end $protect_source_operations$;

